window.SANDBOX_DADOS = {"meta":{"titulo":"Sandboxes regulatórios no Brasil","atualizacaoBase":"2026-10-29","total":24},"temas":[{"id":"turismo","nome":"Turismo","icone":"☀","cor":"#cfe8dc"},{"id":"financas","nome":"Finanças","icone":"¤","cor":"#d6e0f5"},{"id":"energia","nome":"Energia","icone":"⚡","cor":"#f7ecc6"},{"id":"mobilidade","nome":"Mobilidade","icone":"⇄","cor":"#d4e9f2"},{"id":"logistica","nome":"Logística","icone":"▦","cor":"#eadfd2"},{"id":"saude","nome":"Saúde","icone":"✚","cor":"#f4d9dc"},{"id":"dados","nome":"Dados e IA","icone":"◈","cor":"#e2dcf2"},{"id":"cidades","nome":"Cidades inteligentes","icone":"⌂","cor":"#dbe8d4"},{"id":"ambiente","nome":"Meio ambiente","icone":"❦","cor":"#d5ecd9"},{"id":"seguros","nome":"Seguros","icone":"⛨","cor":"#e4e6ea"},{"id":"telecom","nome":"Telecomunicações","icone":"◉","cor":"#d9e4ee"},{"id":"aviacao","nome":"Aviação e drones","icone":"✈","cor":"#dde9f5"},{"id":"startups","nome":"Startups e inovação","icone":"✦","cor":"#f5e1cf"},{"id":"gestao-publica","nome":"Gestão pública","icone":"▤","cor":"#e6e1d6"},{"id":"educacao","nome":"Educação","icone":"✎","cor":"#f2e6cc"},{"id":"seguranca","nome":"Segurança urbana","icone":"◎","cor":"#ece0e6"}],"orgaos":[],"sandboxes":[{"id":"balneario-camboriu","nome":"Sandbox Regulatório de Balneário Camboriú","esfera":"municipal","jurisdicao":{"municipio":"Balneário Camboriú","uf":"SC","regiao":"Sul"},"status":"regulamentado","temas":["startups","cidades","saude","educacao","seguranca"],"resumo":"Decreto de 2025 cria o sandbox do Inova BC; edital de inscrição contínua já recebeu 12 projetos em avaliação.","descricao":"Balneário Camboriú instituiu o Sandbox Regulatório pelo Decreto nº 12.473, de 11 de julho de 2025, dentro da política municipal de incentivo à inovação. O ambiente permite flexibilizar de forma temporária e controlada decretos, portarias e resoluções para viabilizar testes.\n\nA Divisão de Tecnologia da Informação da Secretaria de Governo, Inovação e Orçamento gerencia o edital, que recebe propostas de forma contínua pelo portal Inova BC. Até outubro de 2026, 12 projetos haviam sido inscritos e apresentados em rodadas de sabatina.\n\nAs propostas seguem para uma Comissão Especial de Avaliação, e as autorizações só serão concedidas depois do relatório da comissão; até a data da verificação, nenhum teste havia sido autorizado.","desde":"2025-07-11","gestor":"Divisão de Tecnologia da Informação (DTI) da Secretaria de Governo, Inovação e Orçamento (Segov)","ingresso":"fluxo_continuo","elegibilidade":"Empresas ou entidades com capacidade técnica e financeira, sem condenações por crimes graves e sem impedimento de contratar com o poder público.","flexibilizacoes":["Flexibilização temporária de decretos, portarias e resoluções municipais para viabilizar os testes"],"documentos":[{"tipo":"decreto","titulo":"Portal Inova BC (Sandbox), que remete ao Decreto nº 12.473/2025","numero":"12.473/2025","data":"2025-07-11","url":"https://inova.bc.sc.gov.br/sandbox","principal":true}],"editais":[{"titulo":"Edital do Sandbox Regulatório (inscrições contínuas)","status":"aberto","url":"https://inova.bc.sc.gov.br/sandbox"}],"imagem":{"arquivo":"img/balneario-camboriu.jpg","credito":"Trustable","licenca":"CC BY-SA 4.0","origem":"https://commons.wikimedia.org/wiki/File:Balne%C3%A1rio_Cambori%C3%BA_from_Unipraias_Park_2023-04-02.jpg"},"fontes":[{"url":"https://inova.bc.sc.gov.br/sandbox","titulo":"Inova BC — Sandbox","acessado_em":"2026-10-29"},{"url":"https://folhadoestadosc.com.br/balneario-camboriu-sandbox-regulatorio-terceira-rodada-encerra-apresentacoes-de-projetos-ja-inscritos/","titulo":"Folha do Estado SC — terceira rodada encerra apresentações de projetos (out/2026)","acessado_em":"2026-10-29"},{"url":"https://www.bcnoticias.com.br/balneario-camboriu-cria-projeto-para-impulsionar-startups-e-tecnologia/","titulo":"BC Notícias — Balneário Camboriú cria projeto para impulsionar startups","acessado_em":"2026-10-29"}],"verificado_em":"2026-10-29","historico":[{"data":"2026-10-01","descricao":"Encerrada a terceira rodada de apresentações; 12 projetos inscritos seguem para a Comissão Especial de Avaliação.","fonte":"https://folhadoestadosc.com.br/balneario-camboriu-sandbox-regulatorio-terceira-rodada-encerra-apresentacoes-de-projetos-ja-inscritos/"},{"data":"2025-07-11","descricao":"Publicado o Decreto nº 12.473/2025.","fonte":"https://folhadoestadosc.com.br/balneario-camboriu-sandbox-regulatorio-terceira-rodada-encerra-apresentacoes-de-projetos-ja-inscritos/"}],"recem_adicionado":true},{"id":"belo-horizonte","nome":"Sandbox Regulatório do Marco Municipal das Startups de Belo Horizonte","esfera":"municipal","jurisdicao":{"municipio":"Belo Horizonte","uf":"MG","regiao":"Sudeste"},"status":"regulamentado","temas":["startups"],"resumo":"Lei de 2025 (Marco Municipal das Startups) prevê sandbox regulatório e CPSI; regulamentação específica não localizada.","descricao":"Belo Horizonte publicou em abril de 2025 a Lei nº 11.838/2025, conhecida como Marco Municipal das Startups, originada do PL 1012/2024 e aprovada por unanimidade na Câmara Municipal.\n\nA lei prevê um programa de sandbox regulatório, pelo qual órgãos municipais podem oferecer condições especiais simplificadas para que empresas testem modelos de negócio e tecnologias experimentais por tempo determinado. O mesmo texto trata do Contrato Público para Solução Inovadora (CPSI) e de um regime simplificado para startups.\n\nNão foram localizados decreto de regulamentação do sandbox, chamamentos ou testes realizados.","desde":"2025-04-01","ingresso":"nao_informado","documentos":[{"tipo":"lei","titulo":"Lei do Marco Municipal das Startups (inclui o sandbox regulatório)","numero":"11.838/2025","data":"2025-04-01","url":"https://www.cmbh.mg.gov.br/comunica%C3%A7%C3%A3o/not%C3%ADcias/2025/04/nova-lei-favorece-pesquisa-tecnol%C3%B3gica-e-desenvolvimento-de-startups","principal":true},{"tipo":"outro","titulo":"Projeto de Lei nº 1012/2024 (aprovado em 2º turno)","url":"https://www.cmbh.mg.gov.br/comunica%C3%A7%C3%A3o/not%C3%ADcias/2025/02/aprovado-em-definitivo-marco-regulat%C3%B3rio-das-startups-em-bh"}],"imagem":{"arquivo":"img/belo-horizonte.jpg","credito":"Marina Campos Vinhal","licenca":"CC BY 2.0","origem":"https://commons.wikimedia.org/wiki/File:Praca_do_Papa,_Belo_Horizonte_(cropped)2.jpg"},"fontes":[{"url":"https://www.cmbh.mg.gov.br/comunica%C3%A7%C3%A3o/not%C3%ADcias/2025/04/nova-lei-favorece-pesquisa-tecnol%C3%B3gica-e-desenvolvimento-de-startups","titulo":"Câmara Municipal de Belo Horizonte — Nova lei favorece pesquisa tecnológica e desenvolvimento de startups","acessado_em":"2026-10-29"},{"url":"https://www.cmbh.mg.gov.br/comunica%C3%A7%C3%A3o/not%C3%ADcias/2025/02/aprovado-em-definitivo-marco-regulat%C3%B3rio-das-startups-em-bh","titulo":"Câmara Municipal de Belo Horizonte — Aprovado em definitivo marco regulatório das startups","acessado_em":"2026-10-29"},{"url":"https://www.otempo.com.br/politica/2025/4/1/prefeito-alvaro-damiao-sanciona-marco-municipal-das-startups-em-belo-horizonte","titulo":"O Tempo — Prefeito sanciona Marco Municipal das Startups","acessado_em":"2026-10-29"}],"verificado_em":"2026-10-29","historico":[{"data":"2025-04-01","descricao":"Lei nº 11.838/2025 publicada no Diário Oficial do Município; o registro anterior citava apenas o PL 1012/2024 aprovado.","fonte":"https://www.otempo.com.br/politica/2025/4/1/prefeito-alvaro-damiao-sanciona-marco-municipal-das-startups-em-belo-horizonte"},{"data":"2025-02-05","descricao":"Câmara aprova o PL 1012/2024 em 2º turno.","fonte":"https://www.cmbh.mg.gov.br/comunica%C3%A7%C3%A3o/not%C3%ADcias/2025/02/aprovado-em-definitivo-marco-regulat%C3%B3rio-das-startups-em-bh"}],"recem_adicionado":false},{"id":"blumenau","nome":"Zonas de Desenvolvimento, Inovação e Tecnologia (Regulatory Sandbox) de Blumenau","esfera":"municipal","jurisdicao":{"municipio":"Blumenau","uf":"SC","regiao":"Sul"},"status":"regulamentado","temas":["startups","cidades"],"resumo":"Lei complementar de 2021 cria zonas de inovação no formato de ambiente regulatório experimental, regulamentadas por decreto.","descricao":"Blumenau aprovou a Lei Complementar nº 1.338, de 20 de maio de 2021, que estabelece normas gerais para zonas de desenvolvimento, inovação e tecnologia organizadas como ambiente regulatório experimental, também chamado de Regulatory Sandbox. A lei foi regulamentada pelo Decreto nº 13.555/2021.\n\nO projeto teve origem na Câmara Municipal e altera dispositivos de outra lei complementar municipal. Não foram localizadas informações públicas sobre chamamentos, empresas autorizadas ou testes realizados.","desde":"2021-05-20","ingresso":"nao_informado","documentos":[{"tipo":"lei","titulo":"Lei Complementar sobre zonas de desenvolvimento, inovação e tecnologia em ambiente regulatório experimental","numero":"1.338/2021","data":"2021-05-20","url":"https://leismunicipais.com.br/a/sc/b/blumenau/lei-complementar/2021/133/1338/lei-complementar-n-1338-2021-dispoe-sobre-a-constituicao-e-estabelece-normas-gerais-para-funcionamento-de-zonas-de-desenvolvimento-inovacao-e-tecnologia-a-serem-organizadas-na-forma-de-ambiente-regulatorio-experimental-no-municipio-de-blumenau-e-acrescenta-dispositivos-conexos-nos-artigos-227-264-e-341-da-lei-complementar-n-632-de-30-de-marco-de-2007","principal":true},{"tipo":"decreto","titulo":"Decreto que regulamenta a Lei Complementar nº 1.338/2021","numero":"13.555/2021","url":"https://leismunicipais.com.br/a/sc/b/blumenau/decreto/2021/1356/13555/decreto-n-13555-2021-regulamenta-a-lei-complementar-n-1338-de-20-de-maio-de-2021-que-dispoe-sobre-a-constituicao-e-estabelece-normas-gerais-para-funcionamento-de-zonas-de-desenvolvimento-inovacao-e-tecnologia-a-serem-organizadas-na-forma-de-ambiente-regulatorio-experimental-no-municipio-de-blumenau-e-acrescenta-dispositivos-conexos-nos-artigos-227-264-e-341-da-lei-complementar-n-632-de-30-de-marco-de-2007"}],"imagem":{"arquivo":"img/blumenau.jpg","credito":"charles242","licenca":"CC BY 3.0","origem":"https://commons.wikimedia.org/wiki/File:Foto_a%C3%A9rea_Blumenau.jpg"},"fontes":[{"url":"https://leismunicipais.com.br/a/sc/b/blumenau/lei-complementar/2021/133/1338/lei-complementar-n-1338-2021-dispoe-sobre-a-constituicao-e-estabelece-normas-gerais-para-funcionamento-de-zonas-de-desenvolvimento-inovacao-e-tecnologia-a-serem-organizadas-na-forma-de-ambiente-regulatorio-experimental-no-municipio-de-blumenau-e-acrescenta-dispositivos-conexos-nos-artigos-227-264-e-341-da-lei-complementar-n-632-de-30-de-marco-de-2007","titulo":"Leis Municipais — Lei Complementar nº 1.338/2021 de Blumenau","acessado_em":"2026-10-29"},{"url":"https://leismunicipais.com.br/a/sc/b/blumenau/decreto/2021/1356/13555/decreto-n-13555-2021-regulamenta-a-lei-complementar-n-1338-de-20-de-maio-de-2021-que-dispoe-sobre-a-constituicao-e-estabelece-normas-gerais-para-funcionamento-de-zonas-de-desenvolvimento-inovacao-e-tecnologia-a-serem-organizadas-na-forma-de-ambiente-regulatorio-experimental-no-municipio-de-blumenau-e-acrescenta-dispositivos-conexos-nos-artigos-227-264-e-341-da-lei-complementar-n-632-de-30-de-marco-de-2007","titulo":"Leis Municipais — Decreto nº 13.555/2021 de Blumenau","acessado_em":"2026-10-29"},{"url":"https://camarablu.sc.gov.br/detalhe-noticia/9425/aprovado-projeto-que-regulamenta-zonas-de-inovacao-em-blumenau/","titulo":"Câmara Municipal de Blumenau — Aprovado projeto que regulamenta zonas de inovação","acessado_em":"2026-10-29"}],"verificado_em":"2026-10-29","historico":[{"data":"2021-05-20","descricao":"Publicada a Lei Complementar nº 1.338/2021.","fonte":"https://leismunicipais.com.br/a/sc/b/blumenau/lei-complementar/2021/133/1338/lei-complementar-n-1338-2021-dispoe-sobre-a-constituicao-e-estabelece-normas-gerais-para-funcionamento-de-zonas-de-desenvolvimento-inovacao-e-tecnologia-a-serem-organizadas-na-forma-de-ambiente-regulatorio-experimental-no-municipio-de-blumenau-e-acrescenta-dispositivos-conexos-nos-artigos-227-264-e-341-da-lei-complementar-n-632-de-30-de-marco-de-2007"}],"recem_adicionado":true},{"id":"criciuma","nome":"Sandbox Regulatório de Criciúma","esfera":"municipal","jurisdicao":{"municipio":"Criciúma","uf":"SC","regiao":"Sul"},"status":"regulamentado","temas":["startups","cidades"],"resumo":"Decreto de 2022, inspirado no Sandbox.Rio, permite autorizações provisórias de até um ano para startups testarem soluções.","descricao":"Criciúma regulamentou seu sandbox pelo Decreto SG nº 1.241/2022, de julho de 2022, publicado no Diário Oficial do Município em agosto. O texto regulamenta a Lei Complementar federal nº 182/2021 no município e segue o modelo do Rio de Janeiro.\n\nA seleção de participantes ocorre por chamamento público, com autorização provisória de até um ano, coordenada por um Comitê Gestor em parceria com a diretoria de tecnologia da informação. Não foram localizados editais publicados ou testes realizados.","desde":"2022-07-19","gestor":"Comitê Gestor do Sandbox, com a Diretoria de Tecnologia da Informação do Município","ingresso":"edital","prazo_teste_meses":12,"documentos":[{"tipo":"decreto","titulo":"Notícia sobre o Decreto SG nº 1.241/2022, que cria o ambiente regulatório experimental","numero":"1.241/2022","data":"2022-07-19","url":"https://www.engeplus.com.br/noticia/inovacao-e-tecnologia/2022/criciuma-publica-decreto-que-da-primeiro-passo-para-sandbox-regulatorio","principal":true}],"imagem":{"arquivo":"img/criciuma.jpg","credito":"Alcimar Luiz Callegari","licenca":"CC BY-SA 4.0","origem":"https://commons.wikimedia.org/wiki/File:Avenida_Get%C3%BAlio_Vargas,_Crici%C3%BAma_SC.jpg"},"fontes":[{"url":"https://www.engeplus.com.br/noticia/inovacao-e-tecnologia/2022/criciuma-publica-decreto-que-da-primeiro-passo-para-sandbox-regulatorio","titulo":"Engeplus — Criciúma publica decreto que dá primeiro passo para sandbox regulatório (ago/2022)","acessado_em":"2026-10-29"},{"url":"https://portal.tcu.gov.br/data/files/4B/C2/6D/DB/56ABB810F80985A8E18818A8/231108_Sandbox.pdf","titulo":"TCU — estudo \"Sandbox regulatório no Marco Legal das Startups\" (2023), tabela de atos estaduais e municipais","acessado_em":"2026-10-29"}],"verificado_em":"2026-10-29","historico":[{"data":"2022-08-10","descricao":"Decreto publicado no Diário Oficial do Município.","fonte":"https://www.engeplus.com.br/noticia/inovacao-e-tecnologia/2022/criciuma-publica-decreto-que-da-primeiro-passo-para-sandbox-regulatorio"}],"recem_adicionado":false},{"id":"curitiba","nome":"Sandbox.CWB – Ambiente Experimental de Inovação Regulatória de Curitiba","esfera":"municipal","jurisdicao":{"municipio":"Curitiba","uf":"PR","regiao":"Sul"},"status":"ativo","temas":["startups","cidades","aviacao","mobilidade"],"resumo":"Lei municipal de 2024 cria o Sandbox.CWB; testes de entrega por drone e 1º edital aberto em outubro de 2026.","descricao":"Curitiba criou seu programa de sandbox por decreto em 2021 e o consolidou na Lei Municipal nº 16.344, de 19 de junho de 2024, regulamentada pelo Decreto nº 2.447/2025. O programa, hoje chamado Sandbox.CWB, é conduzido pela Secretaria Municipal de Desenvolvimento Econômico e Inovação com apoio de um Comitê Gestor.\n\nAs autorizações temporárias valem por até 12 meses, prorrogáveis por mais 12, e eventuais flexibilizações regulatórias são analisadas caso a caso; a seleção não garante automaticamente a dispensa de regras.\n\nSob o ambiente experimental, a prefeitura firmou parceria com a Atech, do grupo Embraer, para testes de entrega por drone, que resultaram em entrega dos Correios em 2025. Em outubro de 2026 foi publicado o Edital de Chamamento Público nº 02/2026, primeiro ciclo aberto e multissetorial, com até dez projetos.","desde":"2021","gestor":"Secretaria Municipal de Desenvolvimento Econômico e Inovação (SMDEI), com o Comitê Gestor do Sandbox.CWB","ingresso":"edital","prazo_teste_meses":12,"elegibilidade":"Pessoas jurídicas regularmente constituídas e com CNPJ ativo, incluindo startups, microempresas, universidades e organizações da sociedade civil.","flexibilizacoes":["Autorização temporária de uso de bem público vinculada ao cronograma experimental","Flexibilizações regulatórias temporárias analisadas caso a caso, quando juridicamente possíveis"],"documentos":[{"tipo":"lei","titulo":"Lei que institui o Sandbox Regulatório de Curitiba","numero":"16.344/2024","data":"2024-06-19","url":"https://leismunicipais.com.br/a/pr/c/curitiba/lei-ordinaria/2024/1635/16344/lei-ordinaria-n-16344-2024-dispoe-sobre-as-regras-para-a-constituicao-e-normas-gerais-de-funcionamento-de-ambiente-regulatorio-experimental-no-municipio-de-curitiba","principal":true},{"tipo":"decreto","titulo":"Edital 02/2026 que cita o Decreto nº 2.447/2025 (regulamento da Lei nº 16.344/2024)","numero":"2.447/2025","url":"https://mid.curitiba.pr.gov.br/2026/00466681.pdf"},{"tipo":"decreto","titulo":"Decreto que instituiu o Programa Sandbox Curitiba","numero":"1.885/2021","url":"https://leismunicipais.com.br/a/pr/c/curitiba/decreto/2021/189/1885/decreto-n-1885-2021-regulamenta-no-ambito-do-municipio-de-curitiba-a-instituicao-de-ambientes-experimentais-de-inovacao-cientifica-tecnologica-e-empreendedora-programa-sandbox-curitiba-sob-o-formato-de-bancos-de-testes-regulatorios-e-tecnologicos-no-modelo-sandbox-nos-termos-do-artigo-11-da-lei-complementar-federal-n-182-de-1-de-junho-de-2021"},{"tipo":"edital","titulo":"Edital de Chamamento Público nº 02/2026 – Sandbox.CWB","url":"https://mid.curitiba.pr.gov.br/2026/00466681.pdf"}],"solucoes":[{"nome":"Entrega urbana por drone (operações BVLOS)","proponente":"Atech (grupo Embraer), com Correios e Speedbird Aero","descricao":"Pesquisa e testes de voo de drones de entrega em área urbana, com primeira entrega dos Correios por drone em 2025.","status":"concluida","fonte":"https://www.curitiba.pr.gov.br/noticias/laboratorio-para-servicos-do-futuro-curitiba-recebe-primeiro-delivery-dos-correios-feito-por-drone/76634"}],"editais":[{"titulo":"Edital de Chamamento Público nº 02/2026 – Sandbox.CWB (1º ciclo)","status":"aberto","url":"https://mid.curitiba.pr.gov.br/2026/00466681.pdf"}],"imagem":{"arquivo":"img/curitiba.jpg","credito":"Vitor Hirota","licenca":"CC BY-SA 2.0","origem":"https://commons.wikimedia.org/wiki/File:Tangu%C3%A1_Curitiba.jpg"},"fontes":[{"url":"https://mid.curitiba.pr.gov.br/2026/00466681.pdf","titulo":"Prefeitura de Curitiba — Edital de Chamamento Público nº 02/2026 (Sandbox.CWB)","acessado_em":"2026-10-29"},{"url":"https://www.curitiba.pr.gov.br/noticias/prefeitura-abre-edital-para-o-sandboxcwb-programa-testa-solucoes-para-curitiba/85640","titulo":"Prefeitura de Curitiba — Prefeitura abre edital para o Sandbox.CWB","acessado_em":"2026-10-29"},{"url":"https://leismunicipais.com.br/a/pr/c/curitiba/lei-ordinaria/2024/1635/16344/lei-ordinaria-n-16344-2024-dispoe-sobre-as-regras-para-a-constituicao-e-normas-gerais-de-funcionamento-de-ambiente-regulatorio-experimental-no-municipio-de-curitiba","titulo":"Leis Municipais — Lei nº 16.344/2024 de Curitiba","acessado_em":"2026-10-29"},{"url":"https://www.cmc.pr.gov.br/informacao/noticias/lei-do-sandbox-regulatorio-de-curitiba-ja-esta-em-vigor","titulo":"Câmara Municipal de Curitiba — Lei do Sandbox Regulatório já está em vigor","acessado_em":"2026-10-29"},{"url":"https://www.curitiba.pr.gov.br/noticias/laboratorio-para-servicos-do-futuro-curitiba-recebe-primeiro-delivery-dos-correios-feito-por-drone/76634","titulo":"Prefeitura de Curitiba — primeiro delivery dos Correios por drone","acessado_em":"2026-10-29"},{"url":"https://portal.tcu.gov.br/data/files/4B/C2/6D/DB/56ABB810F80985A8E18818A8/231108_Sandbox.pdf","titulo":"TCU — estudo \"Sandbox regulatório no Marco Legal das Startups\" (2023), tabela de atos estaduais e municipais","acessado_em":"2026-10-29"}],"verificado_em":"2026-10-29","historico":[{"data":"2026-10-27","descricao":"Lançado o Edital de Chamamento Público nº 02/2026, 1º ciclo do Sandbox.CWB.","fonte":"https://www.curitiba.pr.gov.br/noticias/prefeitura-abre-edital-para-o-sandboxcwb-programa-testa-solucoes-para-curitiba/85640"},{"data":"2024-06-19","descricao":"Sancionada a Lei nº 16.344/2024, que institui o sandbox regulatório municipal.","fonte":"https://www.cmc.pr.gov.br/informacao/noticias/lei-do-sandbox-regulatorio-de-curitiba-ja-esta-em-vigor"},{"data":"2021-12-02","descricao":"Prefeitura apresenta o Programa Sandbox Curitiba, instituído por decreto.","fonte":"https://www.curitiba.pr.gov.br/noticias/curitiba-adota-ambiente-livre-de-regulacoes-para-validacao-de-tecnologias/61782"}],"recem_adicionado":false},{"id":"df","nome":"Zonas de Desenvolvimento de Inovação e Tecnologia do Distrito Federal","esfera":"estadual","jurisdicao":{"uf":"DF","regiao":"Centro-Oeste"},"status":"regulamentado","temas":["cidades","startups"],"resumo":"Lei distrital de 2020 autoriza zonas de inovação com liberdade de testes; órgão gestor e regulamentação não localizados.","descricao":"O Distrito Federal tem a Lei nº 6.653, de 17 de agosto de 2020, que autoriza a criação de Zonas de Desenvolvimento de Inovação e Tecnologia e trata da liberdade de testes de inovação. A lei foi promulgada pela Câmara Legislativa após a derrubada de veto do governador.\n\nA norma permite ao Executivo delimitar áreas em que podem ser autorizados testes experimentais de novos materiais, produtos, sistemas e serviços, mas deixa a definição do órgão gestor para regulamentação posterior. Não foram localizados decreto regulamentador, chamamentos ou testes.","desde":"2020-08-17","ingresso":"nao_informado","documentos":[{"tipo":"lei","titulo":"Lei distrital sobre Zonas de Desenvolvimento de Inovação e Tecnologia e liberdade de testes","numero":"6.653/2020","data":"2020-08-17","url":"https://www.legisweb.com.br/legislacao/?id=400432","principal":true}],"imagem":{"arquivo":"img/df.jpg","credito":"Arturdiasr","licenca":"CC BY-SA 4.0","origem":"https://commons.wikimedia.org/wiki/File:Planalto_Central_(cropped).jpg"},"fontes":[{"url":"https://www.legisweb.com.br/legislacao/?id=400432","titulo":"LegisWeb — Lei distrital nº 6.653/2020","acessado_em":"2026-10-29"},{"url":"https://portal.tcu.gov.br/data/files/4B/C2/6D/DB/56ABB810F80985A8E18818A8/231108_Sandbox.pdf","titulo":"TCU — estudo \"Sandbox regulatório no Marco Legal das Startups\" (2023), tabela de atos estaduais e municipais","acessado_em":"2026-10-29"}],"verificado_em":"2026-10-29","historico":[{"data":"2026-10-29","descricao":"Registro anterior (\"Decreto s/n\", municipal, sem fonte) substituído pela Lei distrital nº 6.653/2020, identificada no estudo do TCU; esfera ajustada para estadual/distrital.","fonte":"https://portal.tcu.gov.br/data/files/4B/C2/6D/DB/56ABB810F80985A8E18818A8/231108_Sandbox.pdf"}],"recem_adicionado":false},{"id":"foz-do-iguacu","nome":"Programa Sandbox – Foz do Iguaçu (Vila A Inteligente)","esfera":"municipal","jurisdicao":{"municipio":"Foz do Iguaçu","uf":"PR","regiao":"Sul"},"status":"ativo","temas":["cidades","energia","mobilidade"],"resumo":"Bairro Vila A como área de testes de cidade inteligente, com soluções instaladas via chamada Smart Vitrine.","descricao":"Foz do Iguaçu regulamentou em junho de 2020 um ambiente experimental de inovação no formato de bancos de testes regulatórios e tecnológicos. A área escolhida foi o bairro Vila A (Itaipu A), divulgado pelos parceiros como o primeiro bairro brasileiro operando em regime de sandbox.\n\nA seleção de empresas ocorre pela chamada pública Smart Vitrine, conduzida pelo Itaipu Parquetec (antigo PTI-BR) com a ABDI, a Itaipu Binacional e a prefeitura, com apoio de Inmetro e Copel. As soluções são instaladas sem custo para o município e acompanhadas por um comitê gestor.\n\nNo primeiro ciclo foram aprovadas empresas de hidratação pública, coleta de óleo de cozinha, monitoramento de energia e totens com internet sem fio, cujas instalações foram inauguradas em fevereiro de 2022. Não foram localizadas informações públicas sobre ciclos posteriores.","desde":"2020-06-23","gestor":"Comitê Gestor do Programa Sandbox, com Prefeitura, Itaipu Parquetec e ABDI","ingresso":"edital","prazo_teste_meses":12,"elegibilidade":"Empresas com soluções de cidades inteligentes selecionadas em chamada pública, com instalação a título não oneroso.","documentos":[{"tipo":"decreto","titulo":"Decreto que regulamenta o Programa Sandbox – Foz do Iguaçu","numero":"28.244/2020","data":"2020-06-23","url":"https://leismunicipais.com.br/a/pr/f/foz-do-iguacu/decreto/2020/2825/28244/decreto-n-28244-2020-regulamenta-no-ambito-do-municipio-de-foz-do-iguacu-a-instituicao-de-ambientes-experimentais-de-inovacao-cientifica-tecnologica-e-empreendedora-sob-o-formato-de-bancos-de-testes-regulatorios-e-tecnologicos-programa-sandbox-foz-do-iguacu","principal":true},{"tipo":"edital","titulo":"Resumo do Edital Smart Vitrine 01/2021","url":"https://hubiguassu.itaipuparquetec.org.br/wp-content/uploads/2021/07/resumo-EditalSmartVitrine.pdf"}],"solucoes":[{"nome":"Estações de hidratação inteligentes","proponente":"Icehot","descricao":"Estações públicas que fornecem água quente e fria no bairro Vila A.","status":"concluida","fonte":"https://dplnews.com/brasil-bairro-sandbox-ja-e-uma-realidade-no-sul-do-pais/"},{"nome":"Coleta de óleo de cozinha usado","proponente":"Óleoponto","descricao":"Equipamento para facilitar o descarte e a coleta de óleo de cozinha pelos moradores.","status":"concluida","fonte":"https://dplnews.com/brasil-bairro-sandbox-ja-e-uma-realidade-no-sul-do-pais/"},{"nome":"Monitoramento de consumo de energia","proponente":"Bohnen+Messtek","descricao":"Equipamentos de medição e monitoramento do consumo de energia em residências e comércios.","status":"concluida","fonte":"https://dplnews.com/brasil-bairro-sandbox-ja-e-uma-realidade-no-sul-do-pais/"},{"nome":"Totens inteligentes","descricao":"Totens com internet sem fio e recarga de celular, entre outros serviços.","status":"concluida","fonte":"https://dplnews.com/brasil-bairro-sandbox-ja-e-uma-realidade-no-sul-do-pais/"}],"editais":[{"titulo":"Smart Vitrine – Edital 01/2021","status":"encerrado","url":"https://hubiguassu.itaipuparquetec.org.br/wp-content/uploads/2021/07/resumo-EditalSmartVitrine.pdf"}],"imagem":{"arquivo":"img/foz-do-iguacu.jpg","credito":"enioprado","licenca":"CC BY-SA 3.0","origem":"https://commons.wikimedia.org/wiki/File:Foz_do_Igua%C3%A7u_-_panoramio_(cropped).jpg"},"fontes":[{"url":"https://leismunicipais.com.br/a/pr/f/foz-do-iguacu/decreto/2020/2825/28244/decreto-n-28244-2020-regulamenta-no-ambito-do-municipio-de-foz-do-iguacu-a-instituicao-de-ambientes-experimentais-de-inovacao-cientifica-tecnologica-e-empreendedora-sob-o-formato-de-bancos-de-testes-regulatorios-e-tecnologicos-programa-sandbox-foz-do-iguacu","titulo":"Leis Municipais — Decreto nº 28.244/2020 de Foz do Iguaçu","acessado_em":"2026-10-29"},{"url":"https://portal.tcu.gov.br/data/files/4B/C2/6D/DB/56ABB810F80985A8E18818A8/231108_Sandbox.pdf","titulo":"TCU — estudo \"Sandbox regulatório no Marco Legal das Startups\" (2023), tabela de atos estaduais e municipais","acessado_em":"2026-10-29"},{"url":"https://hubiguassu.itaipuparquetec.org.br/wp-content/uploads/2021/07/resumo-EditalSmartVitrine.pdf","titulo":"Itaipu Parquetec — resumo do Edital Smart Vitrine","acessado_em":"2026-10-29"},{"url":"https://dplnews.com/brasil-bairro-sandbox-ja-e-uma-realidade-no-sul-do-pais/","titulo":"DPL News — Bairro Sandbox já é uma realidade no sul do país (fev/2022)","acessado_em":"2026-10-29"},{"url":"https://100fronteiras.com/inovacao/noticia/vila-a-inteligente-conheca-as-seis-empresas-selecionadas/","titulo":"100 Fronteiras — empresas selecionadas para o Vila A Inteligente","acessado_em":"2026-10-29"}],"verificado_em":"2026-10-29","historico":[{"data":"2022-02-14","descricao":"Inauguração oficial das soluções instaladas no bairro Vila A.","fonte":"https://dplnews.com/brasil-bairro-sandbox-ja-e-uma-realidade-no-sul-do-pais/"},{"data":"2020-06-23","descricao":"Publicação do Decreto nº 28.244/2020, que regulamenta o programa.","fonte":"https://portal.tcu.gov.br/data/files/4B/C2/6D/DB/56ABB810F80985A8E18818A8/231108_Sandbox.pdf"}],"recem_adicionado":false},{"id":"goiania","nome":"Programa Sandbox Regulatório Goiânia","esfera":"municipal","jurisdicao":{"municipio":"Goiânia","uf":"GO","regiao":"Centro-Oeste"},"status":"regulamentado","temas":["startups","cidades"],"resumo":"Decreto de 2022, inspirado no Sandbox.Rio, regulamenta ambientes regulatórios experimentais com autorização de até um ano.","descricao":"Goiânia regulamentou o Programa Sandbox Regulatório Goiânia pelo Decreto nº 3.955, de 26 de setembro de 2022, que altera o Decreto nº 3.730/2021 e cria ambientes regulatórios experimentais para inovações científicas, tecnológicas e empreendedoras.\n\nInspirado no modelo do Rio de Janeiro, o programa prevê chamamento público com critérios de elegibilidade e autorizações temporárias de até um ano, que segundo estudo do TCU devem ser veiculadas por decreto do prefeito. Não foram localizados editais ou empresas autorizadas.","desde":"2022-09-26","ingresso":"edital","prazo_teste_meses":12,"documentos":[{"tipo":"decreto","titulo":"Decreto que regulamenta o Programa Sandbox Regulatório Goiânia","numero":"3.955/2022","data":"2022-09-26","url":"https://www.goiania.go.gov.br/html/gabinete_civil/sileg/dados/legis/2022/dc_20220926_000003955.html","principal":true},{"tipo":"decreto","titulo":"Decreto alterado pelo Decreto nº 3.955/2022","numero":"3.730/2021","data":"2021-08-02","url":"https://www.goiania.go.gov.br/html/gabinete_civil/sileg/dados/legis/2021/dc_20210802_000003730.html"}],"imagem":{"arquivo":"img/goiania.jpg","credito":"Boaventuravinicius","licenca":"CC BY-SA 4.0","origem":"https://commons.wikimedia.org/wiki/File:Panomara_Goi%C3%A2nia_2022.jpg"},"fontes":[{"url":"https://www.goiania.go.gov.br/html/gabinete_civil/sileg/dados/legis/2022/dc_20220926_000003955.html","titulo":"Prefeitura de Goiânia — Decreto nº 3.955/2022","acessado_em":"2026-10-29"},{"url":"https://portal.tcu.gov.br/data/files/4B/C2/6D/DB/56ABB810F80985A8E18818A8/231108_Sandbox.pdf","titulo":"TCU — estudo \"Sandbox regulatório no Marco Legal das Startups\" (2023), tabela de atos estaduais e municipais","acessado_em":"2026-10-29"}],"verificado_em":"2026-10-29","historico":[{"data":"2026-10-29","descricao":"Fonte corrigida: o link anterior tratava do sandbox da agência estadual (AGR), não do programa municipal.","fonte":"https://www.goiania.go.gov.br/html/gabinete_civil/sileg/dados/legis/2022/dc_20220926_000003955.html"},{"data":"2022-09-26","descricao":"Publicado o Decreto nº 3.955/2022.","fonte":"https://www.goiania.go.gov.br/html/gabinete_civil/sileg/dados/legis/2022/dc_20220926_000003955.html"}],"recem_adicionado":false},{"id":"jaragua-do-sul","nome":"Programa Sandbox Regulatório – Jaraguá do Sul","esfera":"municipal","jurisdicao":{"municipio":"Jaraguá do Sul","uf":"SC","regiao":"Sul"},"status":"regulamentado","temas":["startups","cidades"],"resumo":"Lei de 2025 reformula o sandbox municipal criado em 2021: chamamento público obrigatório e permissões de até dois anos.","descricao":"Jaraguá do Sul instituiu seu sandbox regulatório pela Lei Municipal nº 8.746, de julho de 2021, regulamentada pelo Decreto nº 15.202/2021. Em 2025 o programa foi reformulado pela Lei nº 9.960/2025 e pelo Decreto nº 19.504/2025, que revogaram a norma anterior.\n\nA nova regra torna obrigatório o chamamento público, restringe a participação a empresas constituídas e sediadas no município e prevê permissões temporárias de até um ano, prorrogáveis por igual período com aprovação do Conselho Municipal de Inovação. A flexibilização alcança apenas normas municipais.\n\nSegundo a prefeitura, apenas quatro empresas se habilitaram na versão anterior do programa; não foram localizadas fontes públicas que identifiquem soluções em teste. Em setembro de 2026 foi lançado o Edital de Chamamento Público nº 001/SEDEIN/2026, válido por um ano.","desde":"2021-07-20","gestor":"Secretaria Municipal de Desenvolvimento Econômico e Inovação (SEDEIN), com o Comitê de Sandbox","ingresso":"edital","prazo_teste_meses":12,"elegibilidade":"Empresas já constituídas, com sede em Jaraguá do Sul, que arquem com os custos de instalação, operação e retirada dos protótipos.","flexibilizacoes":["Suspensão temporária de normas municipais específicas (não abrange legislação federal ou ambiental)","Permissão temporária de uso de bens e espaços públicos"],"documentos":[{"tipo":"lei","titulo":"Lei que reformula o Programa Sandbox Regulatório e revoga a Lei nº 8.746/2021","numero":"9.960/2025","data":"2025-07-16","url":"https://leismunicipais.com.br/a/sc/j/jaragua-do-sul/lei-ordinaria/2025/996/9960/lei-ordinaria-n-9960-2025-regulamenta-a-constituicao-e-estabelece-normas-e-condicoes-especiais-aos-modelos-de-negocios-que-buscam-desenvolvimento-inovacao-e-tecnologia-em-ambiente-regulatorio-experimental-denominado-programa-sandbox-regulatorio-jaragua-do-sul-e-revoga-a-lei-municipal-n-8746-2021-de-20-de-julho-de-2021","principal":true},{"tipo":"decreto","titulo":"Decreto que regulamenta a Lei nº 9.960/2025","numero":"19.504/2025","url":"https://leismunicipais.com.br/a/sc/j/jaragua-do-sul/decreto/2025/1951/19504/decreto-n-19504-2025-regulamenta-o-funcionamento-do-ambiente-regulatorio-inovador-e-experimental-tambem-denominado-programa-sandbox-regulatorio-jaragua-do-sul-instituido-pela-lei-municipal-n-9960-2025-de-16-de-julho-de-2025"},{"tipo":"lei","titulo":"Lei que instituiu o Sandbox Regulatório (revogada)","numero":"8.746/2021","data":"2021-07-20","url":"https://www.jaraguadosul.sc.gov.br/news/lunelli-sanciona-lei-que-institui-o-sandbox-regulat-rio"},{"tipo":"outro","titulo":"Projeto de Lei nº 177/2025 (origem da nova lei)","url":"https://www.legislador.com.br//LegisladorWEB.ASP?WCI=ProjetoTexto&inEspecie=1&nrProjeto=177&aaProjeto=2025&ID=5"}],"editais":[{"titulo":"Edital de Chamamento Público nº 001/SEDEIN/2026 (vigência de um ano)","status":"aberto","url":"https://observamais.com.br/municipio-lanca-edital-de-chamamento-publico-ao/"}],"imagem":{"arquivo":"img/jaragua-do-sul.jpg","credito":"Giro720","licenca":"CC BY-SA 4.0","origem":"https://commons.wikimedia.org/wiki/File:Jaragu%C3%A1_do_Sul_Landscape.jpg"},"fontes":[{"url":"https://leismunicipais.com.br/a/sc/j/jaragua-do-sul/lei-ordinaria/2025/996/9960/lei-ordinaria-n-9960-2025-regulamenta-a-constituicao-e-estabelece-normas-e-condicoes-especiais-aos-modelos-de-negocios-que-buscam-desenvolvimento-inovacao-e-tecnologia-em-ambiente-regulatorio-experimental-denominado-programa-sandbox-regulatorio-jaragua-do-sul-e-revoga-a-lei-municipal-n-8746-2021-de-20-de-julho-de-2021","titulo":"Leis Municipais — Lei nº 9.960/2025 de Jaraguá do Sul","acessado_em":"2026-10-29"},{"url":"https://leismunicipais.com.br/a/sc/j/jaragua-do-sul/decreto/2025/1951/19504/decreto-n-19504-2025-regulamenta-o-funcionamento-do-ambiente-regulatorio-inovador-e-experimental-tambem-denominado-programa-sandbox-regulatorio-jaragua-do-sul-instituido-pela-lei-municipal-n-9960-2025-de-16-de-julho-de-2025","titulo":"Leis Municipais — Decreto nº 19.504/2025 de Jaraguá do Sul","acessado_em":"2026-10-29"},{"url":"https://observamais.com.br/municipio-lanca-edital-de-chamamento-publico-ao/","titulo":"Observa Mais — Município lança edital de chamamento público ao Programa Sandbox (set/2026)","acessado_em":"2026-10-29"},{"url":"https://www.jaraguadosul.sc.gov.br/noticias/nova-lei-do-programa-sandbox-regulatorio-entra-em-vigor","titulo":"Prefeitura de Jaraguá do Sul — Nova lei do Programa Sandbox Regulatório entra em vigor (ago/2025)","acessado_em":"2026-10-29"},{"url":"https://www.jaraguadosul.sc.gov.br/news/lunelli-sanciona-lei-que-institui-o-sandbox-regulat-rio","titulo":"Prefeitura de Jaraguá do Sul — Lunelli sanciona lei que institui o Sandbox Regulatório","acessado_em":"2026-10-29"},{"url":"https://portal.tcu.gov.br/data/files/4B/C2/6D/DB/56ABB810F80985A8E18818A8/231108_Sandbox.pdf","titulo":"TCU — estudo \"Sandbox regulatório no Marco Legal das Startups\" (2023), tabela de atos estaduais e municipais","acessado_em":"2026-10-29"}],"verificado_em":"2026-10-29","historico":[{"data":"2026-10-29","descricao":"Status revisto de \"ativo\" para \"regulamentado\": não foi localizada fonte pública que documente solução em teste.","fonte":"https://www.jaraguadosul.sc.gov.br/noticias/nova-lei-do-programa-sandbox-regulatorio-entra-em-vigor"},{"data":"2026-09-01","descricao":"Lançado o Edital de Chamamento Público nº 001/SEDEIN/2026, com vigência de um ano.","fonte":"https://observamais.com.br/municipio-lanca-edital-de-chamamento-publico-ao/"},{"data":"2025-08-12","descricao":"Entra em vigor a Lei nº 9.960/2025, regulamentada pelo Decreto nº 19.504/2025.","fonte":"https://www.jaraguadosul.sc.gov.br/noticias/nova-lei-do-programa-sandbox-regulatorio-entra-em-vigor"},{"data":"2021-07-20","descricao":"Sancionada a Lei nº 8.746/2021, que criou o sandbox municipal.","fonte":"https://www.jaraguadosul.sc.gov.br/news/lunelli-sanciona-lei-que-institui-o-sandbox-regulat-rio"}],"recem_adicionado":false},{"id":"londrina","nome":"Programa Sandbox – Londrina","esfera":"municipal","jurisdicao":{"municipio":"Londrina","uf":"PR","regiao":"Sul"},"status":"regulamentado","temas":["cidades"],"resumo":"Decreto de 2021 regulamenta o Programa Sandbox de Londrina, com a Rua Sergipe como área de testes de cidade inteligente.","descricao":"Londrina regulamentou o Programa Sandbox – Londrina pelo Decreto nº 310, de 15 de março de 2021, publicado no Jornal Oficial do município. O modelo segue o de Foz do Iguaçu: um comitê gestor delibera sobre a criação dos ambientes de teste, com ciclos de 6 a 12 meses renováveis.\n\nA prefeitura apresentou a Rua Sergipe, no centro, como primeira área para que startups testem produtos ainda fora do mercado, no âmbito do projeto Cidade Inteligente. Não foram localizadas informações públicas sobre chamamentos ou testes realizados.","desde":"2021-03-15","gestor":"Comitê Gestor do Programa Sandbox","ingresso":"nao_informado","prazo_teste_meses":12,"documentos":[{"tipo":"decreto","titulo":"Decreto que regulamenta o Programa Sandbox – Londrina (Jornal Oficial nº 4303)","numero":"310/2021","data":"2021-03-15","url":"https://portal.londrina.pr.gov.br/images/stories/jornalOficial/Jornal-4303-Assinado-Pdf.pdf","principal":true}],"imagem":{"arquivo":"img/londrina.jpg","credito":"Lírica Aragão from Londrina, Brasil","licenca":"CC BY-SA 2.0","origem":"https://commons.wikimedia.org/wiki/File:Museu_Municipal_de_Londrina_2.jpg"},"fontes":[{"url":"https://portal.londrina.pr.gov.br/images/stories/jornalOficial/Jornal-4303-Assinado-Pdf.pdf","titulo":"Jornal Oficial de Londrina nº 4303 — Decreto nº 310/2021","acessado_em":"2026-10-29"},{"url":"https://blog.londrina.pr.gov.br/?p=94273","titulo":"Prefeitura de Londrina — Londrina terá uma SandBox (mar/2021)","acessado_em":"2026-10-29"},{"url":"https://portal.tcu.gov.br/data/files/4B/C2/6D/DB/56ABB810F80985A8E18818A8/231108_Sandbox.pdf","titulo":"TCU — estudo \"Sandbox regulatório no Marco Legal das Startups\" (2023), tabela de atos estaduais e municipais","acessado_em":"2026-10-29"}],"verificado_em":"2026-10-29","historico":[{"data":"2026-10-29","descricao":"Registro antes listado como \"Decreto s/n\" e sem fonte; identificado como Decreto nº 310, de 15/03/2021, publicado no Jornal Oficial nº 4303.","fonte":"https://portal.londrina.pr.gov.br/images/stories/jornalOficial/Jornal-4303-Assinado-Pdf.pdf"},{"data":"2021-03-24","descricao":"Prefeitura divulga o decreto e a Rua Sergipe como área de testes.","fonte":"https://blog.londrina.pr.gov.br/?p=94273"}],"recem_adicionado":false},{"id":"macapa","nome":"Programa Sandbox – Macapá","esfera":"municipal","jurisdicao":{"municipio":"Macapá","uf":"AP","regiao":"Norte"},"status":"regulamentado","temas":["cidades","mobilidade"],"resumo":"Decreto de 2021 cria área urbana para testar tecnologias de cidades inteligentes, ligada ao laboratório da ABDI.","descricao":"Macapá instituiu o Programa Sandbox – Macapá por decreto assinado em junho de 2021, durante o lançamento de projeto de mobilidade da ABDI na Companhia de Transportes e Trânsito do município. O estudo do TCU identifica o ato como Decreto nº 4.062/2021.\n\nO decreto permite delimitar uma área urbana em que tecnologias de cidades inteligentes possam ser testadas e validadas, no formato de bancos de testes regulatórios e tecnológicos, com ciclos de 6 a 12 meses. A iniciativa decorre de convênio com a ABDI firmado em 2020, que implantou semáforos inteligentes e um centro de controle.\n\nNão foram localizadas informações públicas sobre chamamentos ou testes de empresas dentro do sandbox.","desde":"2021-06-25","gestor":"Comitê Gestor do Programa Sandbox","ingresso":"nao_informado","prazo_teste_meses":12,"documentos":[{"tipo":"decreto","titulo":"Notícia oficial da prefeitura sobre a assinatura do decreto do Programa Sandbox – Macapá (nº 4.062/2021 segundo o TCU)","numero":"4.062/2021","data":"2021-06-28","url":"https://macapa.ap.gov.br/com-assinatura-de-decreto-prefeitura-cria-sandbox-para-uso-das-tecnologias-de-cidades-inteligentes-em-macapa/","principal":true}],"imagem":{"arquivo":"img/macapa.jpg","credito":"Márcia do Carmo / MTur","licenca":"Public domain","origem":"https://commons.wikimedia.org/wiki/File:Orla_de_Macap%C3%A1,_Amap%C3%A1.jpg"},"fontes":[{"url":"https://macapa.ap.gov.br/com-assinatura-de-decreto-prefeitura-cria-sandbox-para-uso-das-tecnologias-de-cidades-inteligentes-em-macapa/","titulo":"Prefeitura de Macapá — Com assinatura de decreto, Prefeitura cria sandbox para tecnologias de Cidades Inteligentes","acessado_em":"2026-10-29"},{"url":"https://portal.tcu.gov.br/data/files/4B/C2/6D/DB/56ABB810F80985A8E18818A8/231108_Sandbox.pdf","titulo":"TCU — estudo \"Sandbox regulatório no Marco Legal das Startups\" (2023), tabela de atos estaduais e municipais","acessado_em":"2026-10-29"}],"verificado_em":"2026-10-29","historico":[{"data":"2026-10-29","descricao":"Status revisto de \"em instituição\" para \"regulamentado\": o decreto foi assinado em junho de 2021.","fonte":"https://macapa.ap.gov.br/com-assinatura-de-decreto-prefeitura-cria-sandbox-para-uso-das-tecnologias-de-cidades-inteligentes-em-macapa/"},{"data":"2021-06-25","descricao":"Prefeito assina o decreto do Programa Sandbox na sede da CTMac.","fonte":"https://macapa.ap.gov.br/com-assinatura-de-decreto-prefeitura-cria-sandbox-para-uso-das-tecnologias-de-cidades-inteligentes-em-macapa/"}],"recem_adicionado":false},{"id":"maceio","nome":"Sandbox MCZ – Sandbox Regulatório de Maceió","esfera":"municipal","jurisdicao":{"municipio":"Maceió","uf":"AL","regiao":"Nordeste"},"status":"regulamentado","temas":["startups","cidades"],"resumo":"Decreto de 2022 regulamenta o sandbox; minuta do primeiro edital passou por consulta pública em 2026.","descricao":"Maceió regulamentou seu sandbox regulatório pelo Decreto nº 9.258, de 26 de agosto de 2022, inspirado no modelo do Rio de Janeiro. O decreto combina chamamento público com deliberação de um Comitê Gestor e prevê autorizações de um ano, prorrogáveis por mais um.\n\nEm junho de 2026, a Secretaria de Estratégias Disruptivas e Economia Digital abriu consulta pública sobre a implantação do Sandbox MCZ, com a minuta do primeiro edital disponível para contribuições até 7 de julho. A consulta já foi encerrada; não foram localizados editais publicados ou testes realizados.","desde":"2022-08-26","gestor":"Secretaria de Estratégias Disruptivas e Economia Digital (Sedigi), com Comitê Gestor","ingresso":"edital","prazo_teste_meses":12,"documentos":[{"tipo":"decreto","titulo":"Decreto que dispõe sobre a constituição e o funcionamento do sandbox regulatório de Maceió","numero":"9.258/2022","data":"2022-08-26","url":"https://www-storage.voxtecnologia.com.br/?f=3493&i=publicado_87376_2022-08-26_2a638646cf464b9193fa324044fe94ba.pdf&m=sigpub.publicacao","principal":true},{"tipo":"outro","titulo":"Consulta pública sobre a minuta do edital do Sandbox MCZ","url":"https://sedigi.maceio.al.gov.br/sandbox/"}],"imagem":{"arquivo":"img/maceio.jpg","credito":"André Lage Freitas (original); obra derivada de Wilfredor e Aristeas","licenca":"CC BY-SA 4.0","origem":"https://commons.wikimedia.org/wiki/File:Ponta_Verde_Lighthouse_landscape_-_Macei%C3%B3,_Brazil_(edited).jpg"},"fontes":[{"url":"https://www-storage.voxtecnologia.com.br/?f=3493&i=publicado_87376_2022-08-26_2a638646cf464b9193fa324044fe94ba.pdf&m=sigpub.publicacao","titulo":"Diário Oficial do Município de Maceió nº 6512 (29/08/2022) — Decreto nº 9.258","acessado_em":"2026-10-29"},{"url":"https://sedigi.maceio.al.gov.br/sandbox/","titulo":"Prefeitura de Maceió (Sedigi) — Sandbox MCZ","acessado_em":"2026-10-29"},{"url":"https://maceio.al.gov.br/noticias/sedigi/prefeitura-de-maceio-abre-consulta-publica-para-implantacao-do-sandbox-regulatorio","titulo":"Prefeitura de Maceió — consulta pública para implantação do Sandbox Regulatório (jun/2026)","acessado_em":"2026-10-29"},{"url":"https://portal.tcu.gov.br/data/files/4B/C2/6D/DB/56ABB810F80985A8E18818A8/231108_Sandbox.pdf","titulo":"TCU — estudo \"Sandbox regulatório no Marco Legal das Startups\" (2023), tabela de atos estaduais e municipais","acessado_em":"2026-10-29"}],"verificado_em":"2026-10-29","historico":[{"data":"2026-06-23","descricao":"Aberta consulta pública sobre a implantação do Sandbox MCZ e a minuta de edital, até 7 de julho de 2026.","fonte":"https://maceio.al.gov.br/noticias/sedigi/prefeitura-de-maceio-abre-consulta-publica-para-implantacao-do-sandbox-regulatorio"},{"data":"2022-08-29","descricao":"Decreto nº 9.258/2022 publicado no Diário Oficial do Município.","fonte":"https://www-storage.voxtecnologia.com.br/?f=3493&i=publicado_87376_2022-08-26_2a638646cf464b9193fa324044fe94ba.pdf&m=sigpub.publicacao"}],"recem_adicionado":false},{"id":"olimpia","nome":"Sandbox Olímpia","esfera":"municipal","jurisdicao":{"municipio":"Olímpia","uf":"SP","regiao":"Sudeste"},"status":"regulamentado","temas":["cidades","startups"],"resumo":"Lei de 2025 institui bancos de testes regulatórios e tecnológicos para inovação científica, tecnológica e urbanística.","descricao":"Olímpia instituiu o Sandbox Olímpia pela Lei nº 5.128, de 2 de julho de 2025, de autoria do Executivo, com base no Marco Legal das Startups e na Lei de Liberdade Econômica. A norma cria ambientes experimentais de inovação científica, tecnológica, urbanística e empreendedora no formato de bancos de testes regulatórios.\n\nO Conselho Municipal de Inovação define critérios e limites para as autorizações temporárias. O portal da prefeitura descreve o sandbox como instrumento para que empresas, startups e instituições de pesquisa testem soluções em ambiente real, com acompanhamento municipal; não foram localizados editais ou testes em andamento.","desde":"2025-07-02","gestor":"Conselho Municipal de Inovação","ingresso":"nao_informado","documentos":[{"tipo":"lei","titulo":"Lei que institui o Sandbox Olímpia","numero":"5.128/2025","data":"2025-07-02","url":"https://legislacaodigital.com.br/Olimpia-SP/LeisOrdinarias/5128-2025?Export=Pdf","principal":true}],"imagem":{"arquivo":"img/olimpia.jpg","credito":"Prefeitura de Olímpia","licenca":"CC BY-SA 4.0","origem":"https://commons.wikimedia.org/wiki/File:Ol%C3%ADmpia_do_Alto.jpg"},"fontes":[{"url":"https://legislacaodigital.com.br/Olimpia-SP/LeisOrdinarias/5128-2025?Export=Pdf","titulo":"Legislação Digital — Lei nº 5.128/2025 de Olímpia","acessado_em":"2026-10-29"},{"url":"https://www.olimpia.sp.gov.br/portal/servicos/1073/o-que-e","titulo":"Prefeitura de Olímpia — Sandbox: o que é","acessado_em":"2026-10-29"}],"verificado_em":"2026-10-29","historico":[{"data":"2025-07-02","descricao":"Sancionada a Lei nº 5.128/2025.","fonte":"https://legislacaodigital.com.br/Olimpia-SP/LeisOrdinarias/5128-2025?Export=Pdf"}],"recem_adicionado":true},{"id":"petrolina","nome":"Sandbox Regulatório de Inovação de Petrolina (SRIP)","esfera":"municipal","jurisdicao":{"municipio":"Petrolina","uf":"PE","regiao":"Nordeste"},"status":"regulamentado","temas":["cidades","gestao-publica"],"resumo":"Decreto de 2025 institui o sandbox de cidades inteligentes, com ciclos por edital de até 12 meses e comitê gestor.","descricao":"Petrolina instituiu o Sandbox Regulatório de Inovação (SRIP) pelo Decreto nº 139, de 5 de novembro de 2025, como parte do Programa Municipal de Ambiente Regulatório Experimental de Cidades Inteligentes e da política municipal de ciência, tecnologia e inovação (Lei nº 3.484/2021).\n\nA Secretaria Municipal de Desenvolvimento Econômico e Inovação coordena a operação, e um Comitê Gestor do Sandbox delibera e supervisiona as experimentações. Cada ciclo é aberto por edital de chamamento público e dura no máximo 12 meses, prorrogáveis uma vez.\n\nEm 2020, a prefeitura havia anunciado um decreto de sandbox ligado ao laboratório vivo de cidades inteligentes da ABDI, mas esse ato anterior não foi localizado em fonte oficial. Não foram localizados editais publicados sob o decreto de 2025.","desde":"2025-11-05","gestor":"Secretaria Municipal de Desenvolvimento Econômico e Inovação, com o Comitê Gestor do Sandbox","ingresso":"edital","prazo_teste_meses":12,"elegibilidade":"Startups, empresas de base tecnológica, ICTs, associações, organizações da sociedade civil, parcerias público-privadas, instituições de ensino com atuação no município e microempresas inovadoras.","documentos":[{"tipo":"decreto","titulo":"Decreto que institui o Programa Municipal de Ambiente Regulatório Experimental de Cidades Inteligentes","numero":"139/2025","data":"2025-11-05","url":"https://petrolina.pe.gov.br/wp-content/uploads/2025/12/DECRETO_139-.pdf","principal":true},{"tipo":"lei","titulo":"Estudo do TCU que cita a Lei nº 3.484/2021 (política municipal de Ciência, Tecnologia e Inovação)","numero":"3.484/2021","data":"2021-12-16","url":"https://portal.tcu.gov.br/data/files/4B/C2/6D/DB/56ABB810F80985A8E18818A8/231108_Sandbox.pdf"}],"imagem":{"arquivo":"img/petrolina.jpg","credito":"Sitenl","licenca":"CC BY-SA 4.0","origem":"https://commons.wikimedia.org/wiki/File:Vista_a%C3%A9rea_lateral_de_Petrolina.jpg"},"fontes":[{"url":"https://petrolina.pe.gov.br/wp-content/uploads/2025/12/DECRETO_139-.pdf","titulo":"Prefeitura de Petrolina — Decreto nº 139/2025","acessado_em":"2026-10-29"},{"url":"https://anapec.org.br/petrolina-ganha-laboratorio-vivo-para-cidades-inteligentes/","titulo":"ANAPEC — Petrolina ganha laboratório vivo para Cidades Inteligentes (2020)","acessado_em":"2026-10-29"},{"url":"https://portal.tcu.gov.br/data/files/4B/C2/6D/DB/56ABB810F80985A8E18818A8/231108_Sandbox.pdf","titulo":"TCU — estudo \"Sandbox regulatório no Marco Legal das Startups\" (2023), tabela de atos estaduais e municipais","acessado_em":"2026-10-29"}],"verificado_em":"2026-10-29","historico":[{"data":"2026-10-29","descricao":"Registro anterior (\"Decreto s/n\", 2021, sem fonte) substituído pelo Decreto nº 139/2025, localizado no site da prefeitura.","fonte":"https://petrolina.pe.gov.br/wp-content/uploads/2025/12/DECRETO_139-.pdf"},{"data":"2025-11-05","descricao":"Publicado o Decreto nº 139/2025, que institui o SRIP.","fonte":"https://petrolina.pe.gov.br/wp-content/uploads/2025/12/DECRETO_139-.pdf"}],"recem_adicionado":false},{"id":"porto-alegre","nome":"Programa Sandbox Porto Alegre","esfera":"municipal","jurisdicao":{"municipio":"Porto Alegre","uf":"RS","regiao":"Sul"},"status":"regulamentado","temas":["startups","cidades"],"resumo":"Lei e decreto de 2022 criam o sandbox municipal, gerido pelo Gabinete da Inovação, para testes em espaços públicos.","descricao":"Porto Alegre criou o Sandbox Regulatório pela Lei nº 13.001, de 27 de janeiro de 2022, e regulamentou o Programa Sandbox Porto Alegre pelo Decreto nº 21.543, de 27 de junho de 2022. As autorizações temporárias valem por até um ano, prorrogáveis por igual período.\n\nA gestão é do Gabinete da Inovação. A prefeitura publica chamadas de interesse para propostas de teste em ambientes públicos, e a empresa deve justificar quais normas pretende afastar e indicar um responsável pelo acompanhamento.\n\nNa página oficial do serviço, a seção de editais ainda não lista chamamentos publicados.","desde":"2022-01-27","gestor":"Gabinete da Inovação (GI-SMGG)","ingresso":"edital","prazo_teste_meses":12,"elegibilidade":"Empresas com capacidade técnica e financeira, sem impedimento de contratar com a administração pública, que indiquem as normas a afastar e um representante.","flexibilizacoes":["Afastamento justificado de normas municipais específicas durante o teste","Flexibilização do horário de funcionamento, prevista na lei"],"documentos":[{"tipo":"decreto","titulo":"Decreto que dispõe sobre o Programa Sandbox Porto Alegre","numero":"21.543/2022","data":"2022-06-27","url":"https://prefeitura.poa.br/carta-de-servicos/sandbox-regulatorio","principal":true},{"tipo":"lei","titulo":"Lei que regulamenta o ambiente regulatório experimental (Sandbox Regulatório)","numero":"13.001/2022","data":"2022-01-27","url":"https://www.camarapoa.rs.gov.br/draco/processos/136852/Lei_13001.pdf"}],"imagem":{"arquivo":"img/porto-alegre.jpg","credito":"Otávio Astor Vaz Costa","licenca":"CC BY-SA 4.0","origem":"https://commons.wikimedia.org/wiki/File:Orla_do_Gua%C3%ADba_2.jpg"},"fontes":[{"url":"https://prefeitura.poa.br/carta-de-servicos/sandbox-regulatorio","titulo":"Prefeitura de Porto Alegre — Carta de Serviços: Sandbox Regulatório","acessado_em":"2026-10-29"},{"url":"https://www.camarapoa.rs.gov.br/draco/processos/136852/Lei_13001.pdf","titulo":"Câmara Municipal de Porto Alegre — Lei nº 13.001/2022","acessado_em":"2026-10-29"},{"url":"https://portal.tcu.gov.br/data/files/4B/C2/6D/DB/56ABB810F80985A8E18818A8/231108_Sandbox.pdf","titulo":"TCU — estudo \"Sandbox regulatório no Marco Legal das Startups\" (2023), tabela de atos estaduais e municipais","acessado_em":"2026-10-29"}],"verificado_em":"2026-10-29","historico":[{"data":"2022-07-18","descricao":"Lançamento do Programa Sandbox Porto Alegre.","fonte":"https://prefeitura.poa.br/gp/noticias/porto-alegre-inova-ao-lancar-sandbox-regulatorio"},{"data":"2022-06-27","descricao":"Publicado o Decreto nº 21.543/2022.","fonte":"https://prefeitura.poa.br/carta-de-servicos/sandbox-regulatorio"}],"recem_adicionado":false},{"id":"recife","nome":"EITA Labs – Recife Living Labs","esfera":"municipal","jurisdicao":{"municipio":"Recife","uf":"PE","regiao":"Nordeste"},"status":"ativo","temas":["cidades","mobilidade","saude","ambiente"],"resumo":"Sandbox urbano criado por decreto em 2022, com testes no espaço público e um sandbox digital (Conecta Labs).","descricao":"O Recife instituiu em abril de 2022, pelo Decreto nº 35.511/2022, ambientes experimentais de inovação no formato de bancos de testes regulatórios e tecnológicos, chamados Recife Living Labs e operados sob a marca EITA Labs.\n\nUm Conselho Gestor pode autorizar a suspensão temporária de regras municipais durante os testes, e uma equipe técnica acompanha os experimentos. Há dois ambientes: o sandbox físico, no espaço urbano, e o sandbox digital Conecta Labs, ligado aos serviços digitais da prefeitura.\n\nA página oficial lista como em experimentação soluções de patinetes elétricos compartilhados, monitoramento de pontes, alerta de alagamentos e serviços digitais de saúde e mobilidade. A participação se dá por editais periódicos.","desde":"2022-04-01","gestor":"Conselho Gestor do EITA Labs, com a Emprel e a Prefeitura do Recife","ingresso":"edital","prazo_teste_meses":12,"flexibilizacoes":["Suspensão temporária da eficácia de normas municipais durante o período de testes, autorizada pelo Conselho Gestor"],"documentos":[{"tipo":"decreto","titulo":"Decreto que regulamenta os ambientes experimentais de inovação (Recife Living Labs)","numero":"35.511/2022","data":"2022-04-01","url":"https://www.legisweb.com.br/legislacao/?id=429903","principal":true},{"tipo":"edital","titulo":"Editais do EITA Labs","url":"https://eitalabs.recife.pe.gov.br/editais/"}],"solucoes":[{"nome":"Patinetes Whoosh","proponente":"Whoosh","descricao":"Patinetes elétricos compartilhados, listados pelo EITA Labs como em experimentação.","status":"em_teste","fonte":"https://eitalabs.recife.pe.gov.br/solucoes/"},{"nome":"Patinetes JET","proponente":"JET","descricao":"Patinetes elétricos compartilhados, listados pelo EITA Labs como em experimentação.","status":"em_teste","fonte":"https://eitalabs.recife.pe.gov.br/solucoes/"},{"nome":"TPF – Sistema de Monitoramento de Pontes","proponente":"TPF","descricao":"Sistema de monitoramento de pontes, listado como em experimentação.","status":"em_teste","fonte":"https://eitalabs.recife.pe.gov.br/solucoes/"},{"nome":"Ih, Alagou","descricao":"Solução ligada a alagamentos urbanos, listada como em experimentação.","status":"em_teste","fonte":"https://eitalabs.recife.pe.gov.br/solucoes/"},{"nome":"Kangoo Saúde","descricao":"Solução de saúde em teste no sandbox digital Conecta Labs.","status":"em_teste","fonte":"https://eitalabs.recife.pe.gov.br/solucoes/"},{"nome":"Mova-se Pelo Futuro!","descricao":"Solução em teste no sandbox digital Conecta Labs.","status":"em_teste","fonte":"https://eitalabs.recife.pe.gov.br/solucoes/"}],"editais":[{"titulo":"Edital 2025 – Inovação para o Futuro","status":"aberto","url":"https://eitalabs.recife.pe.gov.br/editais/edital-atual/"},{"titulo":"Edital 1º Ciclo / 2022","status":"encerrado","url":"https://eitalabs.recife.pe.gov.br/editais/1-ciclo-2022/"}],"imagem":{"arquivo":"img/recife.jpg","credito":"Portal da Copa/ME","licenca":"CC BY 3.0 br","origem":"https://commons.wikimedia.org/wiki/File:Antonio_Vaz_island_-_Recife,_Pernambuco,_Brazil_(cropped).jpg"},"fontes":[{"url":"https://eitalabs.recife.pe.gov.br/","titulo":"EITA Labs — página oficial","acessado_em":"2026-10-29"},{"url":"https://eitalabs.recife.pe.gov.br/solucoes/","titulo":"EITA Labs — soluções implantadas","acessado_em":"2026-10-29"},{"url":"https://eitalabs.recife.pe.gov.br/editais/","titulo":"EITA Labs — editais","acessado_em":"2026-10-29"},{"url":"https://portal.tcu.gov.br/data/files/4B/C2/6D/DB/56ABB810F80985A8E18818A8/231108_Sandbox.pdf","titulo":"TCU — estudo \"Sandbox regulatório no Marco Legal das Startups\" (2023), tabela de atos estaduais e municipais","acessado_em":"2026-10-29"}],"verificado_em":"2026-10-29","historico":[{"data":"2022-04-01","descricao":"Publicado o Decreto nº 35.511/2022, que institui os Recife Living Labs.","fonte":"https://www2.recife.pe.gov.br/noticias/25/08/2022/eita-recife-vence-como-melhor-projeto-publico-e-governamental-dentro-do"}],"recem_adicionado":false},{"id":"rio-de-janeiro","nome":"Sandbox.Rio","esfera":"municipal","jurisdicao":{"municipio":"Rio de Janeiro","uf":"RJ","regiao":"Sudeste"},"status":"ativo","temas":["mobilidade","cidades","ambiente","logistica","energia","saude"],"resumo":"Criado por decreto em 2022 e instituído por lei em 2026; está no III ciclo, e os patinetes testados já têm regulação permanente.","descricao":"O Sandbox.Rio foi criado pelo Decreto Rio nº 50.697, de 26 de abril de 2022, que fixa regras para ambientes regulatórios controlados sob gestão da secretaria municipal de desenvolvimento econômico. Em maio de 2026, a Lei Complementar nº 300/2026 passou a instituir o sandbox por lei, com autorizações de até 12 meses prorrogáveis por igual período.\n\nA seleção ocorre por comunicados e chamadas públicas, com critérios de capacidade técnica e financeira e de idoneidade dos sócios. O III ciclo, anunciado em abril de 2026, recebeu 55 inscrições e selecionou dez projetos em temas como meio ambiente, saúde, mobilidade e logística.\n\nO serviço de patinetes elétricos compartilhados da Whoosh, em operação experimental desde 2024, foi o primeiro projeto do programa a receber regulação permanente, com o Decreto nº 57.657, de março de 2026.","desde":"2022-04-26","gestor":"Secretaria Municipal de Desenvolvimento Econômico (Subsecretaria de Regulação e Ambiente de Negócios)","ingresso":"edital","prazo_teste_meses":12,"elegibilidade":"Pessoas jurídicas com capacidade técnica e financeira comprovada, cujos sócios e administradores não tenham condenações nem impedimentos de contratar com a administração pública.","flexibilizacoes":["Afastamento temporário de normas infralegais municipais, sem alcançar normas que reproduzam texto de lei","Autorização temporária com dispensa de requisitos regulatórios e salvaguardas fixadas previamente"],"documentos":[{"tipo":"lei","titulo":"Lei Complementar que institui o ambiente regulatório controlado (sandbox regulatório) no Município do Rio de Janeiro","numero":"300/2026","data":"2026-05-18","url":"https://www.legisweb.com.br/legislacao/?id=495954","principal":true},{"tipo":"decreto","titulo":"Decreto que dispõe sobre o ambiente regulatório controlado (sandbox regulatório)","numero":"50.697/2022","data":"2022-04-26","url":"https://doweb.rio.rj.gov.br/apifront/portal/edicoes/imprimir_materia/825386/5322"},{"tipo":"decreto","titulo":"Decreto que regulamenta o sistema de patinetes elétricos compartilhados após o teste no Sandbox.Rio","numero":"57.657/2026","url":"https://www.mobiletime.com.br/noticias/10/03/2026/patinetes-rio-de-janeiro/"}],"solucoes":[{"nome":"Patinetes elétricos compartilhados","proponente":"Whoosh","descricao":"Operação experimental com até 1.200 patinetes na Zona Sul e no Centro, depois convertida em regulação permanente.","status":"concluida","fim":"2026-03-10","fonte":"https://analise.com/noticias/como-o-sandbox-regulatorio-esta-destravando-a-inovacao"},{"nome":"Drone de salvamento em praias","proponente":"Aerolabs","descricao":"Drone com visão computacional para identificar afogamentos e lançar boias de salvamento.","status":"selecionada","fonte":"https://www.mobiletime.com.br/noticias/02/04/2026/prefeitura-sandbox-rio/"},{"nome":"Áreas de Revitalização Econômica (Projeto ARE)","proponente":"Aliança Cidade","descricao":"Parceria público-privada para requalificação de áreas do Centro, com mobiliário e moderação de tráfego.","status":"selecionada","fonte":"https://www.mobiletime.com.br/noticias/02/04/2026/prefeitura-sandbox-rio/"},{"nome":"Sensores de qualidade do ar e ruído","proponente":"Bettair","descricao":"Sensores em mobiliário urbano que medem poluição do ar e sonora em tempo real.","status":"selecionada","fonte":"https://www.mobiletime.com.br/noticias/02/04/2026/prefeitura-sandbox-rio/"},{"nome":"Bicicletas aquáticas coletoras de resíduos","proponente":"Biclen (BDM)","descricao":"Bicicletas aquáticas elétricas que recolhem resíduos flutuantes, a começar pela Lagoa Rodrigo de Freitas.","status":"selecionada","fonte":"https://www.mobiletime.com.br/noticias/02/04/2026/prefeitura-sandbox-rio/"},{"nome":"Transporte refrigerado de medicamentos","proponente":"ColdLog","descricao":"Módulos refrigerados em motos elétricas, com monitoramento de temperatura, para vacinas e medicamentos.","status":"selecionada","fonte":"https://www.mobiletime.com.br/noticias/02/04/2026/prefeitura-sandbox-rio/"},{"nome":"Criança Protegida","proponente":"Tooda","descricao":"Pulseiras com QR code para localização de crianças perdidas em praias.","status":"selecionada","fonte":"https://www.mobiletime.com.br/noticias/02/04/2026/prefeitura-sandbox-rio/"},{"nome":"HRios CoreStation 4.0","proponente":"HRios","descricao":"Estação flutuante com IA para coleta de resíduos e monitoramento da água em rios e canais.","status":"selecionada","fonte":"https://www.mobiletime.com.br/noticias/02/04/2026/prefeitura-sandbox-rio/"},{"nome":"Motofog","proponente":"Motofog","descricao":"Motocicletas com nebulização para combate a vetores em áreas de difícil acesso.","status":"selecionada","fonte":"https://www.mobiletime.com.br/noticias/02/04/2026/prefeitura-sandbox-rio/"},{"nome":"Logística de última milha em comunidades","proponente":"naPorta","descricao":"Entregas de varejistas feitas por moradores de comunidades.","status":"selecionada","fonte":"https://www.mobiletime.com.br/noticias/02/04/2026/prefeitura-sandbox-rio/"},{"nome":"Rio Eletrohub","proponente":"Recar","descricao":"Hub de recarga de veículos e bicicletas e troca de baterias alimentado por energia solar.","status":"selecionada","fonte":"https://www.mobiletime.com.br/noticias/02/04/2026/prefeitura-sandbox-rio/"}],"editais":[{"titulo":"Sandbox.Rio – III Ciclo","status":"encerrado","url":"https://www.mobiletime.com.br/noticias/02/04/2026/prefeitura-sandbox-rio/"},{"titulo":"Sandbox.Rio – edital de 2022 (I Ciclo)","status":"encerrado","url":"https://www.mobiletime.com.br/noticias/02/05/2022/rio-de-janeiro-publica-edital-para-projetos-em-sandbox-regulatorio"}],"imagem":{"arquivo":"img/rio-de-janeiro.jpg","credito":"Rafael Rabello de Barros","licenca":"CC BY-SA 3.0","origem":"https://commons.wikimedia.org/wiki/File:Cidade_Maravilhosa.jpg"},"fontes":[{"url":"https://www.legisweb.com.br/legislacao/?id=495954","titulo":"LegisWeb — Lei Complementar nº 300/2026 do Município do Rio de Janeiro","acessado_em":"2026-10-29"},{"url":"https://doweb.rio.rj.gov.br/apifront/portal/edicoes/imprimir_materia/825386/5322","titulo":"Diário Oficial do Município do Rio de Janeiro — Decreto Rio nº 50.697/2022","acessado_em":"2026-10-29"},{"url":"https://www.mobiletime.com.br/noticias/02/04/2026/prefeitura-sandbox-rio/","titulo":"Mobile Time — Sandbox.Rio anuncia selecionados do III Ciclo (abr/2026)","acessado_em":"2026-10-29"},{"url":"https://analise.com/noticias/como-o-sandbox-regulatorio-esta-destravando-a-inovacao","titulo":"Análise — Como o sandbox regulatório está destravando a inovação","acessado_em":"2026-10-29"},{"url":"https://www.mobiletime.com.br/noticias/10/03/2026/patinetes-rio-de-janeiro/","titulo":"Mobile Time — Rio regulamenta patinetes compartilhados (mar/2026)","acessado_em":"2026-10-29"}],"verificado_em":"2026-10-29","historico":[{"data":"2026-05-18","descricao":"Sancionada a Lei Complementar nº 300/2026, que institui o sandbox regulatório por lei; documento principal atualizado.","fonte":"https://www.legisweb.com.br/legislacao/?id=495954"},{"data":"2026-04-02","descricao":"Anunciados os dez selecionados do III Ciclo, entre 55 inscritos.","fonte":"https://www.mobiletime.com.br/noticias/02/04/2026/prefeitura-sandbox-rio/"},{"data":"2026-03-10","descricao":"Publicado o Decreto nº 57.657/2026, que torna permanente o serviço de patinetes testado no programa.","fonte":"https://analise.com/noticias/como-o-sandbox-regulatorio-esta-destravando-a-inovacao"},{"data":"2022-04-26","descricao":"Assinado o Decreto Rio nº 50.697/2022.","fonte":"https://doweb.rio.rj.gov.br/apifront/portal/edicoes/imprimir_materia/825386/5322"}],"recem_adicionado":false},{"id":"sao-jose-dos-campos","nome":"Programa Sandbox São José dos Campos","esfera":"municipal","jurisdicao":{"municipio":"São José dos Campos","uf":"SP","regiao":"Sudeste"},"status":"ativo","temas":["cidades","mobilidade","ambiente","saude","energia","seguranca"],"resumo":"Lei de 2023 cria bancos de testes geridos pelo Parque de Inovação Tecnológica; dois ciclos de seleção já realizados.","descricao":"São José dos Campos instituiu o Programa Sandbox pela Lei nº 10.675, de 3 de abril de 2023, como bancos de testes regulatórios e tecnológicos baseados no Marco Legal das Startups. A gestão cabe ao Parque de Inovação Tecnológica (PIT), com um Comitê Gestor que pode solicitar a suspensão temporária de normas municipais de natureza fiscal, econômica ou urbanística.\n\nO primeiro ciclo recebeu mais de 30 propostas e pré-selecionou seis projetos, com ciclos experimentais de 6 a 12 meses e sem custo para a prefeitura. Um deles, uma plataforma de inteligência artificial para monitoramento por câmeras, foi testado em piloto no Centro em 2025.\n\nO segundo ciclo teve inscrições em outubro de 2025, com seleção final prevista para dezembro daquele ano e implantação a partir de 2026.","desde":"2023-04-03","gestor":"Parque de Inovação Tecnológica (PIT), com o Comitê Gestor do programa","ingresso":"edital","prazo_teste_meses":12,"elegibilidade":"Startups e empresas de base tecnológica brasileiras, com CNPJ, capacidade técnica e financeira e produtos ou serviços inovadores.","flexibilizacoes":["Suspensão temporária de legislação municipal de natureza fiscal, econômica ou urbanística, mediante parecer do Comitê Gestor"],"documentos":[{"tipo":"lei","titulo":"Lei que institui o Programa Sandbox São José","numero":"10.675/2023","data":"2023-04-03","url":"https://servicos.sjc.sp.gov.br/Legislacao/Arquivos/Leis/2023/LE_2023_00010675.pdf","principal":true},{"tipo":"decreto","titulo":"Decreto que nomeia os membros do Comitê Gestor","numero":"19.911/2025","data":"2025-03-27","url":"https://servicos.sjc.sp.gov.br/Legislacao/compilada/31653"}],"solucoes":[{"nome":"IA e visão computacional no monitoramento urbano","proponente":"Erione, com a startup Deepneuronic","descricao":"Análise de imagens de câmeras para detectar situações suspeitas e acionar alertas; piloto de 60 dias com seis câmeras no Centro.","status":"concluida","inicio":"2025-06-16","fonte":"https://pitsjc.org.br/noticias/gerais/tecnologia-desenvolvida-no-pit-e-testada-para-reforcar-a-seguranca-urbana-de-sao-jose-dos-campos/"},{"nome":"Totem para travessia segura","proponente":"Ebrax Indústria e Comércio Ltda.","descricao":"Totem de sinalização sonora e luminosa para proteção de pedestres.","status":"selecionada","fonte":"https://www.sjc.sp.gov.br/noticias/2024/dezembro/10/sandbox-seleciona-projetos-inovadores-em-sao-jose/"},{"nome":"Mobilidade limpa e conservação da biodiversidade","proponente":"Hybrid E-Controls Tecnologia Automotiva Ltda.","descricao":"Hibridização de caminhão de lixo e ônibus urbano, com compensação de emissões.","status":"selecionada","fonte":"https://www.sjc.sp.gov.br/noticias/2024/dezembro/10/sandbox-seleciona-projetos-inovadores-em-sao-jose/"},{"nome":"Pegada de carbono do aterro sanitário","proponente":"Scink Consultoria em Processos Ambientais e Carbon Management Ltda.","descricao":"Medição direta de emissões de metano no aterro municipal.","status":"selecionada","fonte":"https://www.sjc.sp.gov.br/noticias/2024/dezembro/10/sandbox-seleciona-projetos-inovadores-em-sao-jose/"},{"nome":"Gamificação com biofeedback para neurodiversidades","proponente":"Self Aplicações Tecnológicas para Saúde, Educação e Bem-Estar Ltda.","descricao":"Jogos terapêuticos com sensores fisiológicos para crianças com autismo e TDAH.","status":"selecionada","fonte":"https://www.sjc.sp.gov.br/noticias/2024/dezembro/10/sandbox-seleciona-projetos-inovadores-em-sao-jose/"},{"nome":"Gestão de utilidades para energia","proponente":"Tecsus Tecnologias para a Sustentabilidade S.A.","descricao":"Telemetria de energia e gestão automatizada de faturas em prédios públicos.","status":"selecionada","fonte":"https://www.sjc.sp.gov.br/noticias/2024/dezembro/10/sandbox-seleciona-projetos-inovadores-em-sao-jose/"}],"editais":[{"titulo":"Programa Sandbox – 2º Ciclo Experimental","status":"encerrado","abertura":"2025-10-06","encerramento":"2025-10-24","url":"https://www.sjc.sp.gov.br/noticias/2025/outubro/06/s%C3%A3o-jos%C3%A9-abre-inscri%C3%A7%C3%B5es-para-a-2%C2%AA-edi%C3%A7%C3%A3o-do-programa-sandbox/"},{"titulo":"Programa Sandbox – 1º Ciclo Experimental","status":"encerrado","url":"https://www.sjc.sp.gov.br/noticias/2024/dezembro/10/sandbox-seleciona-projetos-inovadores-em-sao-jose/"}],"imagem":{"arquivo":"img/sao-jose-dos-campos.jpg","credito":"Bertachini","licenca":"CC BY-SA 4.0","origem":"https://commons.wikimedia.org/wiki/File:Banhado_S%C3%A3o_Jos%C3%A9_dos_Campos.jpg"},"fontes":[{"url":"https://pitsjc.org.br/sandbox/","titulo":"PIT São José dos Campos — página do Programa Sandbox","acessado_em":"2026-10-29"},{"url":"https://www.sjc.sp.gov.br/noticias/2024/dezembro/10/sandbox-seleciona-projetos-inovadores-em-sao-jose/","titulo":"Prefeitura de São José dos Campos — Sandbox seleciona projetos inovadores","acessado_em":"2026-10-29"},{"url":"https://www.sjc.sp.gov.br/noticias/2025/outubro/06/s%C3%A3o-jos%C3%A9-abre-inscri%C3%A7%C3%B5es-para-a-2%C2%AA-edi%C3%A7%C3%A3o-do-programa-sandbox/","titulo":"Prefeitura de São José dos Campos — inscrições para a 2ª edição","acessado_em":"2026-10-29"},{"url":"https://pitsjc.org.br/noticias/gerais/tecnologia-desenvolvida-no-pit-e-testada-para-reforcar-a-seguranca-urbana-de-sao-jose-dos-campos/","titulo":"PIT — tecnologia testada para reforçar a segurança urbana","acessado_em":"2026-10-29"},{"url":"https://servicos.sjc.sp.gov.br/Legislacao/Arquivos/Leis/2023/LE_2023_00010675.pdf","titulo":"Prefeitura de São José dos Campos — Lei nº 10.675/2023","acessado_em":"2026-10-29"}],"verificado_em":"2026-10-29","historico":[{"data":"2025-10-06","descricao":"Abertas as inscrições do 2º ciclo do programa.","fonte":"https://www.sjc.sp.gov.br/noticias/2025/outubro/06/s%C3%A3o-jos%C3%A9-abre-inscri%C3%A7%C3%B5es-para-a-2%C2%AA-edi%C3%A7%C3%A3o-do-programa-sandbox/"},{"data":"2025-06-16","descricao":"Teste simulado da plataforma de monitoramento urbano por IA, primeiro piloto do programa.","fonte":"https://pitsjc.org.br/noticias/gerais/tecnologia-desenvolvida-no-pit-e-testada-para-reforcar-a-seguranca-urbana-de-sao-jose-dos-campos/"},{"data":"2024-12-10","descricao":"Pré-seleção de seis projetos no 1º ciclo.","fonte":"https://www.sjc.sp.gov.br/noticias/2024/dezembro/10/sandbox-seleciona-projetos-inovadores-em-sao-jose/"},{"data":"2023-04-03","descricao":"Sancionada a Lei nº 10.675/2023.","fonte":"https://servicos.sjc.sp.gov.br/Legislacao/Arquivos/Leis/2023/LE_2023_00010675.pdf"}],"recem_adicionado":false},{"id":"sao-jose-dos-pinhais","nome":"Sandbox SJP","esfera":"municipal","jurisdicao":{"municipio":"São José dos Pinhais","uf":"PR","regiao":"Sul"},"status":"regulamentado","temas":["cidades","gestao-publica","mobilidade","startups","dados"],"resumo":"Decreto de 2025 institui o Sandbox SJP, gerido pela secretaria de inovação, para testar soluções com regras temporárias.","descricao":"São José dos Pinhais instituiu o Sandbox SJP pelo Decreto nº 6.720, de 29 de julho de 2025, com base na Lei Municipal nº 4.715/2025, que trata da política municipal de inovação, e no Marco Legal das Startups.\n\nO programa é gerido pela Secretaria de Inovação, Modernização e Transformação Digital, com um Comitê Gestor Intersetorial e um observador externo. As áreas prioritárias incluem cidades inteligentes, GovTech, mobilidade urbana e elétrica, agricultura de precisão e inteligência artificial.\n\nNão foram localizadas informações públicas sobre chamamentos ou testes realizados até a data da verificação.","desde":"2025-07-29","gestor":"Secretaria de Inovação, Modernização e Transformação Digital (Simot), com Comitê Gestor Intersetorial","ingresso":"nao_informado","elegibilidade":"Pessoas físicas ou jurídicas com projetos alinhados às áreas prioritárias do município.","documentos":[{"tipo":"decreto","titulo":"Página oficial de inovação que descreve o Decreto nº 6.720/2025 (Sandbox SJP)","numero":"6.720/2025","data":"2025-07-29","url":"https://inovacao.sjp.pr.gov.br/fala-inovacao/sandbox-regulatorio/","principal":true},{"tipo":"lei","titulo":"Página oficial de inovação que cita a Lei nº 4.715/2025 (política municipal de inovação)","numero":"4.715/2025","url":"https://inovacao.sjp.pr.gov.br/fala-inovacao/sandbox-regulatorio/"}],"imagem":{"arquivo":"img/sao-jose-dos-pinhais.jpg","credito":"Clediney Boeira da S… (Panoramio)","licenca":"CC BY 3.0","origem":"https://commons.wikimedia.org/wiki/File:Centro,_S%C3%A3o_Jos%C3%A9_dos_Pinhais_-_PR,_Brazil_-_panoramio.jpg"},"fontes":[{"url":"https://inovacao.sjp.pr.gov.br/fala-inovacao/sandbox-regulatorio/","titulo":"Prefeitura de São José dos Pinhais — Sandbox Regulatório: o que é e como funciona","acessado_em":"2026-10-29"},{"url":"https://foconaprefeitura.com.br/sao-jose-dos-pinhais-lanca-programa-para-testes-de-solucoes-tecnologicas/","titulo":"Foco na Prefeitura — São José dos Pinhais lança programa para testes","acessado_em":"2026-10-29"},{"url":"https://busaocuritiba.com/sao-jose-dos-pinhais-cria-sandbox-regulatorio-para-testes-de-solucoes-tecnologicas/","titulo":"Busão Curitiba — São José dos Pinhais cria sandbox regulatório","acessado_em":"2026-10-29"}],"verificado_em":"2026-10-29","historico":[{"data":"2025-07-29","descricao":"Assinado o Decreto nº 6.720/2025.","fonte":"https://foconaprefeitura.com.br/sao-jose-dos-pinhais-lanca-programa-para-testes-de-solucoes-tecnologicas/"}],"recem_adicionado":true},{"id":"sao-paulo","nome":"Sampa Sandbox","esfera":"municipal","jurisdicao":{"municipio":"São Paulo","uf":"SP","regiao":"Sudeste"},"status":"regulamentado","temas":["cidades","energia","mobilidade","dados","telecom"],"resumo":"Lei de 2022 e decreto de 2023 criam o Sampa Sandbox, com comitê gestor intersecretarial e ciclos de 6 a 12 meses.","descricao":"São Paulo criou o Programa Sampa Sandbox pela Lei nº 17.879, de 30 de dezembro de 2022, nos termos do art. 11 do Marco Legal das Startups; segundo a Secretaria Municipal de Inovação e Tecnologia, o programa foi instituído pelo Decreto nº 62.561/2023.\n\nUm Comitê Gestor com representantes de secretarias municipais, da ADE Sampa, da SP Negócios e da Câmara Municipal define por edital critérios, prazos e regras de seleção, e pode pedir aos órgãos competentes a dispensa ou adaptação temporária de normas específicas.\n\nOs temas previstos incluem cidades inteligentes, redes elétricas inteligentes, recarga de veículos elétricos, mobilidade como serviço, internet das coisas e big data. Não foram localizadas listas públicas de projetos selecionados ou em teste.","desde":"2022-12-30","gestor":"Comitê Gestor do Sampa Sandbox (SMIT, SF, SGM, SMDET, SMUL, SIURB, ADE Sampa, SP Negócios e Câmara Municipal)","ingresso":"edital","prazo_teste_meses":12,"flexibilizacoes":["Dispensa ou adaptação temporária de norma municipal específica, solicitada pelo Comitê Gestor ao órgão competente"],"documentos":[{"tipo":"lei","titulo":"Lei que regulamenta o Programa Sampa Sandbox","numero":"17.879/2022","data":"2022-12-30","url":"https://legislacao.prefeitura.sp.gov.br/leis/lei-17879-de-30-de-dezembro-de-2022","principal":true},{"tipo":"decreto","titulo":"Decreto que institui o Sampa Sandbox (citado pela SMIT)","numero":"62.561/2023","url":"https://prefeitura.sp.gov.br/web/inovacao/w/sampa-sandbox"}],"imagem":{"arquivo":"img/sao-paulo.jpg","credito":"Agent010","licenca":"CC BY-SA 4.0","origem":"https://commons.wikimedia.org/wiki/File:Marginal_Pinheiros_e_Jockey_Club.jpg"},"fontes":[{"url":"https://legislacao.prefeitura.sp.gov.br/leis/lei-17879-de-30-de-dezembro-de-2022","titulo":"Prefeitura de São Paulo — Catálogo de Legislação: Lei nº 17.879/2022","acessado_em":"2026-10-29"},{"url":"https://prefeitura.sp.gov.br/web/inovacao/w/sampa-sandbox","titulo":"Secretaria Municipal de Inovação e Tecnologia — Sampa Sandbox","acessado_em":"2026-10-29"},{"url":"http://sampasandbox.com.br/","titulo":"Sampa Sandbox — site do programa","acessado_em":"2026-10-29"}],"verificado_em":"2026-10-29","historico":[{"data":"2022-12-30","descricao":"Promulgada a Lei nº 17.879/2022.","fonte":"https://legislacao.prefeitura.sp.gov.br/leis/lei-17879-de-30-de-dezembro-de-2022"}],"recem_adicionado":true},{"id":"teresina","nome":"Sandbox Regulatório de Teresina","esfera":"municipal","jurisdicao":{"municipio":"Teresina","uf":"PI","regiao":"Nordeste"},"status":"regulamentado","temas":["startups","ambiente","cidades","saude"],"resumo":"Decreto de 2023 cria bancos de testes regulatórios; nove startups selecionadas assinaram termo de adesão em junho de 2023.","descricao":"Teresina regulamentou ambientes experimentais de inovação científica, tecnológica e urbanística pelo Decreto nº 23.821, de 20 de março de 2023, assinado durante a abertura do evento ClimaTHE23 e baseado no Marco Legal das Startups.\n\nO modelo prevê um Conselho Técnico Municipal de Inovação, que pode solicitar aos órgãos a suspensão de normas de interesse para o projeto, e um Comitê Operacional de Inovação, com ciclos experimentais de 6 a 12 meses.\n\nEm junho de 2023, nove empresas selecionadas por chamamento público assinaram termos de adesão para iniciar testes nas áreas de meio ambiente, gestão urbana e saúde. Não foram localizadas fontes que confirmem o andamento ou a conclusão desses testes.","desde":"2023-03-20","gestor":"Secretaria Municipal de Desenvolvimento Econômico e Turismo (Semdec), com Conselho Técnico Municipal de Inovação e Comitê Operacional de Inovação","ingresso":"edital","prazo_teste_meses":12,"flexibilizacoes":["Suspensão da eficácia de normas municipais e infralegais de interesse do projeto, solicitada pelo Conselho Técnico Municipal de Inovação"],"documentos":[{"tipo":"decreto","titulo":"Decreto que regulamenta ambientes experimentais de inovação científica, tecnológica e urbanística","numero":"23.821/2023","data":"2023-03-20","url":"https://pmt.pi.gov.br/2023/03/21/prefeito-de-teresina-assina-decreto-de-inovacao-sandbox-regulatorio-durante-cerimonia-de-abertura-do-climathe23/","principal":true}],"solucoes":[{"nome":"Concreto com polímeros reciclados","proponente":"Policoncret","descricao":"Concreto de menor impacto ambiental feito com plástico reciclado retirado do oceano.","status":"selecionada","fonte":"https://www.piauinegocios.com.br/noticia/1804-nove-startups-vao-iniciar-testes-de-solucoes-inovadoras-em-teresina"},{"nome":"Plataforma de gestão ambiental","proponente":"Tuxtu","descricao":"Software para licenciamento ambiental, créditos de carbono e arborização urbana.","status":"selecionada","fonte":"https://www.piauinegocios.com.br/noticia/1804-nove-startups-vao-iniciar-testes-de-solucoes-inovadoras-em-teresina"},{"nome":"Monitoramento inteligente de vias","proponente":"GeoVista","descricao":"Monitoramento de segurança, buracos, tráfego e iluminação em vias.","status":"selecionada","fonte":"https://www.piauinegocios.com.br/noticia/1804-nove-startups-vao-iniciar-testes-de-solucoes-inovadoras-em-teresina"},{"nome":"Análise e integração de dados urbanos","proponente":"Scipopulis","descricao":"Processamento, integração e visualização de dados para gestão urbana.","status":"selecionada","fonte":"https://www.piauinegocios.com.br/noticia/1804-nove-startups-vao-iniciar-testes-de-solucoes-inovadoras-em-teresina"},{"nome":"Software de gestão urbana","proponente":"Clurb Software","descricao":"Ferramenta colaborativa para resposta a problemas urbanos.","status":"selecionada","fonte":"https://www.piauinegocios.com.br/noticia/1804-nove-startups-vao-iniciar-testes-de-solucoes-inovadoras-em-teresina"},{"nome":"Digitalização de serviços públicos","proponente":"FocoSmart","descricao":"Digitalização de serviços públicos para os moradores.","status":"selecionada","fonte":"https://www.piauinegocios.com.br/noticia/1804-nove-startups-vao-iniciar-testes-de-solucoes-inovadoras-em-teresina"},{"nome":"Compostagem","proponente":"Ninho do Verde Compostagem","descricao":"Serviços de compostagem residencial, empresarial e para o poder público.","status":"selecionada","fonte":"https://www.piauinegocios.com.br/noticia/1804-nove-startups-vao-iniciar-testes-de-solucoes-inovadoras-em-teresina"},{"nome":"Monitoramento de pacientes","proponente":"Chamou Doutor","descricao":"Monitoramento de pacientes e gestão preventiva em saúde.","status":"selecionada","fonte":"https://www.piauinegocios.com.br/noticia/1804-nove-startups-vao-iniciar-testes-de-solucoes-inovadoras-em-teresina"},{"nome":"Dados de visitas domiciliares","proponente":"Gestão de Dados em Saúde","descricao":"Registro de dados das visitas de agentes comunitários de saúde.","status":"selecionada","fonte":"https://www.piauinegocios.com.br/noticia/1804-nove-startups-vao-iniciar-testes-de-solucoes-inovadoras-em-teresina"}],"editais":[{"titulo":"Edital de Chamamento Público para teste de soluções inovadoras (2023)","status":"encerrado","url":"https://www.piauinegocios.com.br/noticia/1804-nove-startups-vao-iniciar-testes-de-solucoes-inovadoras-em-teresina"}],"imagem":{"arquivo":"img/teresina.jpg","credito":"Alexandro Dias","licenca":"CC BY-SA 4.0","origem":"https://commons.wikimedia.org/wiki/File:Ponte_Estaiada_-_Teresina.jpg"},"fontes":[{"url":"https://pmt.pi.gov.br/2023/03/21/prefeito-de-teresina-assina-decreto-de-inovacao-sandbox-regulatorio-durante-cerimonia-de-abertura-do-climathe23/","titulo":"Prefeitura de Teresina — Prefeito assina decreto de inovação Sandbox Regulatório (mar/2023)","acessado_em":"2026-10-29"},{"url":"https://www.piauinegocios.com.br/noticia/1804-nove-startups-vao-iniciar-testes-de-solucoes-inovadoras-em-teresina","titulo":"Piauí Negócios — Nove startups vão iniciar testes em Teresina (jun/2023)","acessado_em":"2026-10-29"},{"url":"https://portal.tcu.gov.br/data/files/4B/C2/6D/DB/56ABB810F80985A8E18818A8/231108_Sandbox.pdf","titulo":"TCU — estudo \"Sandbox regulatório no Marco Legal das Startups\" (2023), tabela de atos estaduais e municipais","acessado_em":"2026-10-29"}],"verificado_em":"2026-10-29","historico":[{"data":"2023-06-28","descricao":"Nove empresas selecionadas assinam termo de adesão para início das atividades.","fonte":"https://www.piauinegocios.com.br/noticia/1804-nove-startups-vao-iniciar-testes-de-solucoes-inovadoras-em-teresina"},{"data":"2023-03-21","descricao":"Decreto publicado no Diário Oficial do Município.","fonte":"https://pmt.pi.gov.br/2023/03/21/prefeito-de-teresina-assina-decreto-de-inovacao-sandbox-regulatorio-durante-cerimonia-de-abertura-do-climathe23/"}],"recem_adicionado":true},{"id":"teresopolis","nome":"SandBox InovaTerê","esfera":"municipal","jurisdicao":{"municipio":"Teresópolis","uf":"RJ","regiao":"Sudeste"},"status":"ativo","temas":["gestao-publica","cidades","saude","energia"],"resumo":"Sandbox regulamentado em 2023; soluções de Defesa Civil, iluminação e saúde testadas após o edital SandBox InovaTerê.","descricao":"Teresópolis regulamentou o SandBox InovaTerê pelo Decreto Municipal nº 5.939, de março de 2023, inspirado no modelo do Rio de Janeiro. O programa é conduzido pela Secretaria Municipal de Ciência e Tecnologia e funciona como ambiente controlado para testar produtos e serviços.\n\nO primeiro chamamento, Edital nº 04/2023, teve inscrições até novembro de 2023. As empresas homologadas assinaram termos de autorização no início de 2024, com prazo de inserção de um ano e possibilidade de suspensão de atos infralegais municipais durante o teste.\n\nEntre as soluções testadas estão uma plataforma de previsão para a Defesa Civil, a telegestão da iluminação pública com sensores e o monitoramento remoto de idosos no serviço de atenção domiciliar. A prefeitura divulgou as soluções aprovadas como aptas à contratação pelo Marco Legal das Startups.","desde":"2023-03-23","gestor":"Secretaria Municipal de Ciência e Tecnologia","ingresso":"edital","prazo_teste_meses":12,"flexibilizacoes":["Suspensão temporária de atos infralegais municipais de natureza fiscal, econômica, urbanística ou outra, quando cabível"],"documentos":[{"tipo":"decreto","titulo":"Notícia oficial sobre o Decreto nº 5.939/2023, que regulamenta o SandBox Regulatório","numero":"5.939/2023","data":"2023-03-23","url":"https://www.teresopolis.rj.gov.br/sandbox-teresopolis-e-a-segunda-cidade-do-estado-do-rio-a-regulamentar-iniciativa-que-visa-estimular-a-inovacao/","principal":true},{"tipo":"edital","titulo":"Edital de Chamamento Público nº 04/2023 – SandBox InovaTerê 2023","url":"https://www.teresopolis.rj.gov.br/wp-content/uploads/2023/09/Edital-SandBox-InovaTere-2023.pdf"}],"solucoes":[{"nome":"Plataforma de previsão para a Defesa Civil","proponente":"Cittua Tecnologia, Consultoria e Treinamento Ltda.","descricao":"Ferramenta de previsão meteorológica e de situações de emergência usada pela Defesa Civil.","status":"concluida","fonte":"https://www.correiodamanha.com.br/correio-serrano/2024/11/167184-tere-divulga-solucoes-aptas-a-contratacao-via-marco-legal.html"},{"nome":"Telegestão da iluminação pública","proponente":"Smart Lighting","descricao":"Gestão remota da iluminação pública com sensores.","status":"concluida","fonte":"https://www.correiodamanha.com.br/correio-serrano/2024/11/167184-tere-divulga-solucoes-aptas-a-contratacao-via-marco-legal.html"},{"nome":"Monitoramento remoto de idosos","proponente":"Medical Angel Ltda.","descricao":"Monitoramento de sinais vitais de pacientes crônicos por relógios inteligentes, para idosos do Serviço de Atenção Domiciliar.","status":"concluida","fonte":"https://www.correiodamanha.com.br/correio-serrano/2024/11/167184-tere-divulga-solucoes-aptas-a-contratacao-via-marco-legal.html"}],"editais":[{"titulo":"Edital nº 04/2023 – SandBox InovaTerê 2023","status":"encerrado","encerramento":"2023-11-03","url":"https://www.teresopolis.rj.gov.br/wp-content/uploads/2023/09/Edital-SandBox-InovaTere-2023.pdf"}],"imagem":{"arquivo":"img/teresopolis.jpg","credito":"Matheus R. Camacho","licenca":"CC BY-SA 4.0","origem":"https://commons.wikimedia.org/wiki/File:Teres%C3%B3polis_vista_parcial_do_Centro.jpg"},"fontes":[{"url":"https://www.teresopolis.rj.gov.br/sandbox-teresopolis-e-a-segunda-cidade-do-estado-do-rio-a-regulamentar-iniciativa-que-visa-estimular-a-inovacao/","titulo":"Prefeitura de Teresópolis — Teresópolis é a segunda cidade do estado do Rio a regulamentar o SandBox","acessado_em":"2026-10-29"},{"url":"https://www.teresopolis.rj.gov.br/wp-content/uploads/2023/09/Edital-SandBox-InovaTere-2023.pdf","titulo":"Prefeitura de Teresópolis — Edital SandBox InovaTerê 2023","acessado_em":"2026-10-29"},{"url":"https://www.correiodamanha.com.br/correio-serrano/2024/11/167184-tere-divulga-solucoes-aptas-a-contratacao-via-marco-legal.html","titulo":"Correio da Manhã — Terê divulga soluções aptas à contratação via marco legal (nov/2024)","acessado_em":"2026-10-29"},{"url":"https://www.teresopolis.rj.gov.br/sandbox-inovatere-prefeitura-e-empresa-voltada-para-prever-situacoes-de-emergencia-em-defesa-civil-apresentam-ferramenta-para-servidores/","titulo":"Prefeitura de Teresópolis — ferramenta de Defesa Civil apresentada a servidores","acessado_em":"2026-10-29"},{"url":"https://portal.tcu.gov.br/data/files/4B/C2/6D/DB/56ABB810F80985A8E18818A8/231108_Sandbox.pdf","titulo":"TCU — estudo \"Sandbox regulatório no Marco Legal das Startups\" (2023), tabela de atos estaduais e municipais","acessado_em":"2026-10-29"}],"verificado_em":"2026-10-29","historico":[{"data":"2024-11-12","descricao":"Três soluções testadas no SandBox InovaTerê são divulgadas como aprovadas e aptas à contratação pública.","fonte":"https://www.correiodamanha.com.br/correio-serrano/2024/11/167184-tere-divulga-solucoes-aptas-a-contratacao-via-marco-legal.html"},{"data":"2023-03-23","descricao":"Publicado o Decreto nº 5.939/2023, que regulamenta o SandBox Regulatório.","fonte":"https://www.teresopolis.rj.gov.br/sandbox-teresopolis-e-a-segunda-cidade-do-estado-do-rio-a-regulamentar-iniciativa-que-visa-estimular-a-inovacao/"}],"recem_adicionado":false},{"id":"vitoria","nome":"Sandbox Vitória","esfera":"municipal","jurisdicao":{"municipio":"Vitória","uf":"ES","regiao":"Sudeste"},"status":"regulamentado","temas":["cidades","ambiente","dados","gestao-publica"],"resumo":"Decreto de 2025 cria o sandbox municipal, coordenado pela Seges e apoiado pelo Laboratório Urbano Vivo (LUV).","descricao":"Vitória lançou o Sandbox Vitória em 30 de abril de 2025 e publicou o Decreto nº 25.053, de 2 de maio de 2025, no Diário Oficial do Município, com regras para criação e funcionamento do ambiente regulatório experimental.\n\nA Secretaria de Gestão e Planejamento coordena o programa; um Conselho Estratégico concede as autorizações provisórias e um Comitê Técnico analisa e acompanha as propostas, com apoio do Laboratório Urbano Vivo. A entrada se dá por comunicado público com cronograma e critérios.\n\nOs eixos prioritários são soluções baseadas na natureza, resiliência climática, gêmeos digitais e IA na gestão urbana, relação com o cidadão e transformação urbana. Não foram localizadas fontes públicas sobre soluções já em teste.","desde":"2025-04-30","gestor":"Secretaria de Gestão e Planejamento (Seges), com Conselho Estratégico, Comitê Técnico e apoio do Laboratório Urbano Vivo (LUV)","ingresso":"edital","elegibilidade":"Pessoas jurídicas com capacidade técnica e financeira, cujos sócios e administradores não tenham condenações nem impedimentos de contratar com a administração pública.","flexibilizacoes":["Dispensa fundamentada de requisitos regulatórios, com condições, limites e salvaguardas propostas pelo participante"],"documentos":[{"tipo":"decreto","titulo":"Decreto que dispõe sobre as regras do ambiente regulatório experimental – Programa Sandbox de Vitória (DOM nº 2627)","numero":"25.053/2025","data":"2025-05-02","url":"https://diariooficial.vitoria.es.gov.br/ExibirArquivo.aspx?qs=nnmrXIDe5L4hR81FZwDXlD95Q%2fWHOCtXgeCw%2fnRIrFMxQA7S5mwuf0RM3mOCPGtiwqKwtsQd8WTWmli6Dukj2cxgIhJDX9kWux4uc4ZzxTH9Zti7ZlOlmi3fwc%2f8THMh","principal":true}],"imagem":{"arquivo":"img/vitoria.jpg","credito":"Romerito Pontes from São Carlos","licenca":"CC BY 2.0","origem":"https://commons.wikimedia.org/wiki/File:-2016-11-05_ao_13-_Vit%C3%B3ria_94_Romerito_Pontes_(30875449812)_(cropped).jpg"},"fontes":[{"url":"https://diariooficial.vitoria.es.gov.br/ExibirArquivo.aspx?qs=nnmrXIDe5L4hR81FZwDXlD95Q%2fWHOCtXgeCw%2fnRIrFMxQA7S5mwuf0RM3mOCPGtiwqKwtsQd8WTWmli6Dukj2cxgIhJDX9kWux4uc4ZzxTH9Zti7ZlOlmi3fwc%2f8THMh","titulo":"Diário Oficial do Município de Vitória nº 2627 (02/05/2025) — Decreto nº 25.053","acessado_em":"2026-10-29"},{"url":"https://www.vitoria.es.gov.br/noticia/decreto-regulamenta-o-sandbox-vitoria-53242","titulo":"Prefeitura de Vitória — Decreto regulamenta o Sandbox Vitória (mai/2025)","acessado_em":"2026-10-29"}],"verificado_em":"2026-10-29","historico":[{"data":"2026-10-29","descricao":"Status revisto de \"ativo\" para \"regulamentado\": não foi localizada fonte pública que documente solução em teste.","fonte":"https://www.vitoria.es.gov.br/noticia/decreto-regulamenta-o-sandbox-vitoria-53242"},{"data":"2025-05-02","descricao":"Publicação do Decreto nº 25.053/2025 no Diário Oficial do Município.","fonte":"https://diariooficial.vitoria.es.gov.br/ExibirArquivo.aspx?qs=nnmrXIDe5L4hR81FZwDXlD95Q%2fWHOCtXgeCw%2fnRIrFMxQA7S5mwuf0RM3mOCPGtiwqKwtsQd8WTWmli6Dukj2cxgIhJDX9kWux4uc4ZzxTH9Zti7ZlOlmi3fwc%2f8THMh"}],"recem_adicionado":false},{"id":"volta-redonda","nome":"Programa Sandbox – Volta Redonda","esfera":"municipal","jurisdicao":{"municipio":"Volta Redonda","uf":"RJ","regiao":"Sudeste"},"status":"regulamentado","temas":["cidades","telecom","startups"],"resumo":"Decreto de 2022 cria zonas de inovação em todo o município; o 1º ciclo de seleção teve inscrições até junho de 2025.","descricao":"Volta Redonda criou o Programa Sandbox – Volta Redonda pelo Decreto nº 17.021, de 3 de março de 2022, que regulamenta zonas de desenvolvimento com inovação científica, tecnológica e empreendedora. O decreto cita a lei municipal do 5G, a Lei de Inovação federal e o Marco Legal das Startups.\n\nUm Comitê Gestor formado por secretarias municipais, sob coordenação da Secretaria de Desenvolvimento Econômico e Turismo, delibera sobre os testes. Cada ciclo experimental dura até 12 meses, prorrogável por igual período, sem custo para o município.\n\nO primeiro ciclo de seleção teve inscrições encerradas em 12 de junho de 2025. Não foram localizados resultados ou testes iniciados.","desde":"2022-03-03","gestor":"Secretaria Municipal de Desenvolvimento Econômico e Turismo (SMDET), com o Comitê Gestor do programa","ingresso":"edital","prazo_teste_meses":12,"elegibilidade":"Startups, empresas, universidades e demais instituições com produtos, serviços ou modelos de negócio inovadores.","documentos":[{"tipo":"decreto","titulo":"Decreto que institui o Programa Sandbox – Volta Redonda","numero":"17.021/2022","data":"2022-03-03","url":"https://www.voltaredonda.rj.gov.br/sandbox/wp-content/uploads/2022/03/decreto-SANDBOX_17021_2022.pdf","principal":true}],"editais":[{"titulo":"Chamamento público – 1º Ciclo de seleção do Sandbox Regulatório","status":"encerrado","encerramento":"2025-06-12","url":"https://www.voltaredonda.rj.gov.br/comunicacao/noticias/31-smdet/10062-volta-redonda-inscri%C3%A7%C3%B5es-para-empresas-e-startups-testarem-solu%C3%A7%C3%B5es-inovadoras-v%C3%A3o-at%C3%A9-quinta-feira-12/"}],"imagem":{"arquivo":"img/volta-redonda.jpg","credito":"NunysBR","licenca":"CC0","origem":"https://commons.wikimedia.org/wiki/File:Centro_de_Volta_Redonda.png"},"fontes":[{"url":"https://www.voltaredonda.rj.gov.br/sandbox/wp-content/uploads/2022/03/decreto-SANDBOX_17021_2022.pdf","titulo":"Prefeitura de Volta Redonda — Decreto nº 17.021/2022","acessado_em":"2026-10-29"},{"url":"https://www.voltaredonda.rj.gov.br/comunicacao/noticias/31-smdet/10062-volta-redonda-inscri%C3%A7%C3%B5es-para-empresas-e-startups-testarem-solu%C3%A7%C3%B5es-inovadoras-v%C3%A3o-at%C3%A9-quinta-feira-12/","titulo":"Prefeitura de Volta Redonda — inscrições para testar soluções inovadoras (jun/2025)","acessado_em":"2026-10-29"},{"url":"https://portal.tcu.gov.br/data/files/4B/C2/6D/DB/56ABB810F80985A8E18818A8/231108_Sandbox.pdf","titulo":"TCU — estudo \"Sandbox regulatório no Marco Legal das Startups\" (2023), tabela de atos estaduais e municipais","acessado_em":"2026-10-29"}],"verificado_em":"2026-10-29","historico":[{"data":"2025-06-12","descricao":"Encerradas as inscrições do 1º ciclo de seleção.","fonte":"https://www.voltaredonda.rj.gov.br/comunicacao/noticias/31-smdet/10062-volta-redonda-inscri%C3%A7%C3%B5es-para-empresas-e-startups-testarem-solu%C3%A7%C3%B5es-inovadoras-v%C3%A3o-at%C3%A9-quinta-feira-12/"},{"data":"2026-10-29","descricao":"Registro antes baseado em \"referência indireta\"; agora apoiado no texto oficial do Decreto nº 17.021/2022.","fonte":"https://www.voltaredonda.rj.gov.br/sandbox/wp-content/uploads/2022/03/decreto-SANDBOX_17021_2022.pdf"}],"recem_adicionado":false}]};
